// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";

/**
 * @title AtomicSwap
 * @notice Hash Time-Locked Contract (HTLC) for trustless cross-chain atomic swaps
 * @dev Enables direct Token Consciousness Exchange between two parties across chains
 * 
 * How it works:
 * 1. Party A creates swap on Chain 1 with secret hash
 * 2. Party B creates swap on Chain 2 with same secret hash
 * 3. Party A reveals secret and claims Party B's tokens
 * 4. Party B uses revealed secret to claim Party A's tokens
 * 5. If timeout, both parties can refund
 */
contract AtomicSwap is ReentrancyGuard {

    // Swap states
    enum State { EMPTY, OPEN, COMPLETED, REFUNDED, EXPIRED }

    // Swap structure
    struct Swap {
        address initiator;           // Party creating the swap
        address participant;         // Counterparty
        address token;              // Token contract address
        uint256 amount;             // Amount locked
        bytes32 secretHash;         // Hash of secret
        uint256 timelock;           // Expiry timestamp
        State state;                // Current state
    }

    // Swap ID => Swap details
    mapping(bytes32 => Swap) public swaps;

    // Events
    event SwapInitiated(
        bytes32 indexed swapId,
        address indexed initiator,
        address indexed participant,
        address token,
        uint256 amount,
        bytes32 secretHash,
        uint256 timelock
    );

    event SwapCompleted(
        bytes32 indexed swapId,
        address indexed participant,
        bytes32 secret
    );

    event SwapRefunded(
        bytes32 indexed swapId,
        address indexed initiator
    );

    /**
     * @notice Initiate atomic swap
     * @param swapId Unique swap identifier (must match across chains)
     * @param participant Counterparty address
     * @param token Token contract address
     * @param amount Amount to lock
     * @param secretHash Hash of secret (keccak256(secret))
     * @param timelock Expiry timestamp (unix seconds)
     */
    function initiate(
        bytes32 swapId,
        address participant,
        address token,
        uint256 amount,
        bytes32 secretHash,
        uint256 timelock
    ) external nonReentrant {
        require(swaps[swapId].state == State.EMPTY, "Swap already exists");
        require(participant != address(0), "Invalid participant");
        require(participant != msg.sender, "Cannot swap with self");
        require(token != address(0), "Invalid token");
        require(amount > 0, "Amount must be > 0");
        require(secretHash != bytes32(0), "Invalid secret hash");
        require(timelock > block.timestamp, "Timelock must be in future");
        require(timelock <= block.timestamp + 48 hours, "Timelock too far");

        // Transfer tokens to contract
        require(
            IERC20(token).transferFrom(msg.sender, address(this), amount),
            "Transfer failed"
        );

        // Create swap
        swaps[swapId] = Swap({
            initiator: msg.sender,
            participant: participant,
            token: token,
            amount: amount,
            secretHash: secretHash,
            timelock: timelock,
            state: State.OPEN
        });

        emit SwapInitiated(
            swapId,
            msg.sender,
            participant,
            token,
            amount,
            secretHash,
            timelock
        );
    }

    /**
     * @notice Complete swap by revealing secret
     * @param swapId Swap identifier
     * @param secret Pre-image of secretHash
     */
    function complete(
        bytes32 swapId,
        bytes32 secret
    ) external nonReentrant {
        Swap storage swap = swaps[swapId];

        require(swap.state == State.OPEN, "Swap not open");
        require(msg.sender == swap.participant, "Only participant can complete");
        require(block.timestamp < swap.timelock, "Swap expired");
        require(keccak256(abi.encodePacked(secret)) == swap.secretHash, "Invalid secret");

        // Mark as completed
        swap.state = State.COMPLETED;

        // Transfer tokens to participant
        require(
            IERC20(swap.token).transfer(swap.participant, swap.amount),
            "Transfer failed"
        );

        emit SwapCompleted(swapId, swap.participant, secret);
    }

    /**
     * @notice Refund tokens after timelock expires
     * @param swapId Swap identifier
     */
    function refund(bytes32 swapId) external nonReentrant {
        Swap storage swap = swaps[swapId];

        require(swap.state == State.OPEN, "Swap not open");
        require(msg.sender == swap.initiator, "Only initiator can refund");
        require(block.timestamp >= swap.timelock, "Timelock not expired");

        // Mark as refunded
        swap.state = State.REFUNDED;

        // Return tokens to initiator
        require(
            IERC20(swap.token).transfer(swap.initiator, swap.amount),
            "Transfer failed"
        );

        emit SwapRefunded(swapId, swap.initiator);
    }

    /**
     * @notice Get swap details
     * @param swapId Swap identifier
     */
    function getSwap(bytes32 swapId) external view returns (
        address initiator,
        address participant,
        address token,
        uint256 amount,
        bytes32 secretHash,
        uint256 timelock,
        State state
    ) {
        Swap storage swap = swaps[swapId];
        return (
            swap.initiator,
            swap.participant,
            swap.token,
            swap.amount,
            swap.secretHash,
            swap.timelock,
            swap.state
        );
    }

    /**
     * @notice Check if swap is active
     * @param swapId Swap identifier
     */
    function isActive(bytes32 swapId) external view returns (bool) {
        Swap storage swap = swaps[swapId];
        return swap.state == State.OPEN && block.timestamp < swap.timelock;
    }

    /**
     * @notice Check if swap is completable
     * @param swapId Swap identifier
     */
    function isCompletable(bytes32 swapId) external view returns (bool) {
        Swap storage swap = swaps[swapId];
        return swap.state == State.OPEN && block.timestamp < swap.timelock;
    }

    /**
     * @notice Check if swap is refundable
     * @param swapId Swap identifier
     */
    function isRefundable(bytes32 swapId) external view returns (bool) {
        Swap storage swap = swaps[swapId];
        return swap.state == State.OPEN && block.timestamp >= swap.timelock;
    }

    /**
     * @notice Generate swap ID from parameters
     * @dev Ensures same swap ID across chains
     */
    function generateSwapId(
        address initiator,
        address participant,
        uint256 amount,
        bytes32 secretHash,
        uint256 nonce
    ) public pure returns (bytes32) {
        return keccak256(abi.encodePacked(
            initiator,
            participant,
            amount,
            secretHash,
            nonce
        ));
    }
}

contracts/bridges/production/BTCBRBridge.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/security/Pausable.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";
import "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";

/**
 * @title BTCBRBridgeMainnet
 * @notice Bridge contract for BSC Mainnet side
 * @dev Locks BTCBR tokens on mainnet for transfer to private chain
 * 
 * Flow: Lock tokens → Validators sign → Mint on private chain
 */
contract BTCBRBridgeMainnet is Ownable, Pausable, ReentrancyGuard {
    using ECDSA for bytes32;

    // BTCBR token on BSC mainnet
    IERC20 public immutable btcbr;

    // Bridge configuration
    uint256 public requiredSignatures;
    uint256 public minTransferAmount;
    uint256 public maxTransferAmount;
    uint256 public dailyLimit;
    uint256 public bridgeFeePercent; // in basis points (100 = 1%)

    // Validator management
    mapping(address => bool) public validators;
    address[] public validatorList;
    uint256 public validatorCount;

    // Nonce tracking to prevent replay attacks
    mapping(uint256 => bool) public processedNonces;
    uint256 public currentNonce;

    // Daily limit tracking
    mapping(address => mapping(uint256 => uint256)) public dailyTransfers;

    // Statistics
    uint256 public totalLocked;
    uint256 public totalReleased;
    uint256 public totalFees;

    // Events
    event Locked(
        address indexed user,
        address indexed recipient,
        uint256 amount,
        uint256 fee,
        uint256 nonce,
        uint256 timestamp
    );

    event Released(
        address indexed recipient,
        uint256 amount,
        uint256 nonce,
        uint256 timestamp
    );

    event ValidatorAdded(address indexed validator);
    event ValidatorRemoved(address indexed validator);
    event RequiredSignaturesChanged(uint256 newRequirement);
    event FeesWithdrawn(address indexed recipient, uint256 amount);

    /**
     * @notice Initialize bridge with BTCBR token address
     * @param _btcbr Address of BTCBR token on BSC mainnet
     * @param _requiredSignatures Number of validator signatures required
     */
    constructor(
        address _btcbr,
        uint256 _requiredSignatures
    ) {
        require(_btcbr != address(0), "Invalid token address");
        require(_requiredSignatures > 0, "Invalid signature requirement");

        btcbr = IERC20(_btcbr);
        requiredSignatures = _requiredSignatures;

        // Default limits
        minTransferAmount = 100 * 10**18; // 100 BTCBR
        maxTransferAmount = 100_000 * 10**18; // 100,000 BTCBR
        dailyLimit = 500_000 * 10**18; // 500,000 BTCBR
        bridgeFeePercent = 10; // 0.1%
    }

    /**
     * @notice Lock BTCBR tokens to transfer to private chain
     * @param amount Amount of BTCBR to lock
     * @param recipient Address on private chain to receive tokens
     */
    function deposit(
        uint256 amount,
        address recipient
    ) external whenNotPaused nonReentrant {
        require(amount >= minTransferAmount, "Amount below minimum");
        require(amount <= maxTransferAmount, "Amount above maximum");
        require(recipient != address(0), "Invalid recipient");

        // Check daily limit
        uint256 today = block.timestamp / 1 days;
        require(
            dailyTransfers[msg.sender][today] + amount <= dailyLimit,
            "Daily limit exceeded"
        );

        // Calculate fee
        uint256 fee = (amount * bridgeFeePercent) / 10000;
        uint256 netAmount = amount - fee;

        // Transfer tokens to bridge
        require(
            btcbr.transferFrom(msg.sender, address(this), amount),
            "Transfer failed"
        );

        // Update statistics
        totalLocked += netAmount;
        totalFees += fee;
        dailyTransfers[msg.sender][today] += amount;

        // Emit event for relayers
        emit Locked(
            msg.sender,
            recipient,
            netAmount,
            fee,
            currentNonce,
            block.timestamp
        );

        currentNonce++;
    }

    /**
     * @notice Release locked tokens when burned on private chain
     * @param amount Amount to release
     * @param recipient Address to receive tokens
     * @param nonce Unique nonce from private chain burn
     * @param signatures Array of validator signatures
     */
    function withdraw(
        uint256 amount,
        address recipient,
        uint256 nonce,
        bytes[] calldata signatures
    ) external whenNotPaused nonReentrant {
        require(!processedNonces[nonce], "Already processed");
        require(signatures.length >= requiredSignatures, "Insufficient signatures");
        require(recipient != address(0), "Invalid recipient");

        // Verify signatures
        bytes32 message = keccak256(abi.encodePacked(
            amount,
            recipient,
            nonce,
            block.chainid
        ));
        bytes32 ethSignedMessage = message.toEthSignedMessageHash();

        address[] memory signers = new address[](signatures.length);
        for (uint256 i = 0; i < signatures.length; i++) {
            address signer = ethSignedMessage.recover(signatures[i]);
            require(validators[signer], "Invalid validator");

            // Check for duplicate signatures
            for (uint256 j = 0; j < i; j++) {
                require(signers[j] != signer, "Duplicate signature");
            }
            signers[i] = signer;
        }

        // Mark as processed
        processedNonces[nonce] = true;
        totalReleased += amount;

        // Transfer tokens
        require(btcbr.transfer(recipient, amount), "Transfer failed");

        emit Released(recipient, amount, nonce, block.timestamp);
    }

    /**
     * @notice Add a validator
     * @param validator Address of validator to add
     */
    function addValidator(address validator) external onlyOwner {
        require(validator != address(0), "Invalid address");
        require(!validators[validator], "Already validator");

        validators[validator] = true;
        validatorList.push(validator);
        validatorCount++;

        emit ValidatorAdded(validator);
    }

    /**
     * @notice Remove a validator
     * @param validator Address of validator to remove
     */
    function removeValidator(address validator) external onlyOwner {
        require(validators[validator], "Not a validator");
        require(validatorCount > requiredSignatures, "Cannot remove, too few validators");

        validators[validator] = false;
        validatorCount--;

        // Remove from list
        for (uint256 i = 0; i < validatorList.length; i++) {
            if (validatorList[i] == validator) {
                validatorList[i] = validatorList[validatorList.length - 1];
                validatorList.pop();
                break;
            }
        }

        emit ValidatorRemoved(validator);
    }

    /**
     * @notice Update required signature count
     * @param newRequirement New signature requirement
     */
    function setRequiredSignatures(uint256 newRequirement) external onlyOwner {
        require(newRequirement > 0, "Invalid requirement");
        require(newRequirement <= validatorCount, "Exceeds validator count");

        requiredSignatures = newRequirement;
        emit RequiredSignaturesChanged(newRequirement);
    }

    /**
     * @notice Update transfer limits
     */
    function setLimits(
        uint256 _minTransferAmount,
        uint256 _maxTransferAmount,
        uint256 _dailyLimit
    ) external onlyOwner {
        minTransferAmount = _minTransferAmount;
        maxTransferAmount = _maxTransferAmount;
        dailyLimit = _dailyLimit;
    }

    /**
     * @notice Update bridge fee
     * @param newFeePercent New fee in basis points
     */
    function setBridgeFee(uint256 newFeePercent) external onlyOwner {
        require(newFeePercent <= 100, "Fee too high"); // Max 1%
        bridgeFeePercent = newFeePercent;
    }

    /**
     * @notice Withdraw collected fees
     * @param recipient Address to receive fees
     */
    function withdrawFees(address recipient) external onlyOwner {
        require(recipient != address(0), "Invalid recipient");
        uint256 fees = totalFees;
        totalFees = 0;

        require(btcbr.transfer(recipient, fees), "Transfer failed");
        emit FeesWithdrawn(recipient, fees);
    }

    /**
     * @notice Pause bridge operations
     */
    function pause() external onlyOwner {
        _pause();
    }

    /**
     * @notice Unpause bridge operations
     */
    function unpause() external onlyOwner {
        _unpause();
    }

    /**
     * @notice Get list of all validators
     */
    function getValidators() external view returns (address[] memory) {
        return validatorList;
    }

    /**
     * @notice Check if nonce has been processed
     */
    function isNonceProcessed(uint256 nonce) external view returns (bool) {
        return processedNonces[nonce];
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/security/Pausable.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";
import "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";

interface IMintableBTCBR {
    function mint(address to, uint256 amount) external;
    function burn(address from, uint256 amount) external;
}

/**
 * @title BTCBRBridgePrivate
 * @notice Bridge contract for Private BSC Chain side
 * @dev Mints BTCBR when locked on mainnet, burns when withdrawing
 * 
 * Flow: Validators sign → Mint tokens | Burn tokens → Validators sign
 */
contract BTCBRBridgePrivate is Ownable, Pausable, ReentrancyGuard {
    using ECDSA for bytes32;

    IMintableBTCBR public immutable btcbr;

    uint256 public requiredSignatures;
    uint256 public minTransferAmount;
    uint256 public maxTransferAmount;
    uint256 public dailyLimit;

    mapping(address => bool) public validators;
    address[] public validatorList;
    uint256 public validatorCount;

    mapping(uint256 => bool) public processedNonces;
    uint256 public currentNonce;

    mapping(address => mapping(uint256 => uint256)) public dailyTransfers;

    uint256 public totalMinted;
    uint256 public totalBurned;

    event Minted(
        address indexed recipient,
        uint256 amount,
        uint256 nonce,
        uint256 timestamp
    );

    event Burned(
        address indexed user,
        address indexed recipient,
        uint256 amount,
        uint256 nonce,
        uint256 timestamp
    );

    event ValidatorAdded(address indexed validator);
    event ValidatorRemoved(address indexed validator);

    constructor(
        address _btcbr,
        uint256 _requiredSignatures
    ) {
        require(_btcbr != address(0), "Invalid token address");
        require(_requiredSignatures > 0, "Invalid signature requirement");

        btcbr = IMintableBTCBR(_btcbr);
        requiredSignatures = _requiredSignatures;

        minTransferAmount = 100 * 10**18;
        maxTransferAmount = 100_000 * 10**18;
        dailyLimit = 500_000 * 10**18;
    }

    function mint(
        uint256 amount,
        address recipient,
        uint256 nonce,
        bytes[] calldata signatures
    ) external whenNotPaused nonReentrant {
        require(!processedNonces[nonce], "Already processed");
        require(signatures.length >= requiredSignatures, "Insufficient signatures");
        require(recipient != address(0), "Invalid recipient");

        bytes32 message = keccak256(abi.encodePacked(
            amount,
            recipient,
            nonce,
            block.chainid
        ));
        bytes32 ethSignedMessage = message.toEthSignedMessageHash();

        address[] memory signers = new address[](signatures.length);
        for (uint256 i = 0; i < signatures.length; i++) {
            address signer = ethSignedMessage.recover(signatures[i]);
            require(validators[signer], "Invalid validator");

            for (uint256 j = 0; j < i; j++) {
                require(signers[j] != signer, "Duplicate signature");
            }
            signers[i] = signer;
        }

        processedNonces[nonce] = true;
        totalMinted += amount;

        btcbr.mint(recipient, amount);

        emit Minted(recipient, amount, nonce, block.timestamp);
    }

    function burn(uint256 amount, address recipient) external whenNotPaused nonReentrant {
        require(amount >= minTransferAmount, "Amount below minimum");
        require(amount <= maxTransferAmount, "Amount above maximum");
        require(recipient != address(0), "Invalid recipient");

        uint256 today = block.timestamp / 1 days;
        require(
            dailyTransfers[msg.sender][today] + amount <= dailyLimit,
            "Daily limit exceeded"
        );

        btcbr.burn(msg.sender, amount);

        totalBurned += amount;
        dailyTransfers[msg.sender][today] += amount;

        emit Burned(msg.sender, recipient, amount, currentNonce, block.timestamp);

        currentNonce++;
    }

    function addValidator(address validator) external onlyOwner {
        require(validator != address(0), "Invalid address");
        require(!validators[validator], "Already validator");

        validators[validator] = true;
        validatorList.push(validator);
        validatorCount++;

        emit ValidatorAdded(validator);
    }

    function removeValidator(address validator) external onlyOwner {
        require(validators[validator], "Not a validator");
        require(validatorCount > requiredSignatures, "Cannot remove");

        validators[validator] = false;
        validatorCount--;

        for (uint256 i = 0; i < validatorList.length; i++) {
            if (validatorList[i] == validator) {
                validatorList[i] = validatorList[validatorList.length - 1];
                validatorList.pop();
                break;
            }
        }

        emit ValidatorRemoved(validator);
    }

    function setRequiredSignatures(uint256 newRequirement) external onlyOwner {
        require(newRequirement > 0, "Invalid requirement");
        require(newRequirement <= validatorCount, "Exceeds validator count");
        requiredSignatures = newRequirement;
    }

    function setLimits(
        uint256 _minTransferAmount,
        uint256 _maxTransferAmount,
        uint256 _dailyLimit
    ) external onlyOwner {
        minTransferAmount = _minTransferAmount;
        maxTransferAmount = _maxTransferAmount;
        dailyLimit = _dailyLimit;
    }

    function pause() external onlyOwner {
        _pause();
    }

    function unpause() external onlyOwner {
        _unpause();
    }

    function getValidators() external view returns (address[] memory) {
        return validatorList;
    }
}

