// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";

interface IXHTRevenue {
    function addRevenue() external payable;
}

/**
 * @title XaheenDEXPair
 * @notice Liquidity pair for Xaheen DEX (Uniswap V2 style)
 * @dev Automated Market Maker with constant product formula (x * y = k)
 */
contract XaheenDEXPair is ERC20, ReentrancyGuard {

    address public token0;
    address public token1;
    address public factory;
    address public revenueContract;

    uint256 public reserve0;
    uint256 public reserve1;
    uint256 public blockTimestampLast;

    uint256 public price0CumulativeLast;
    uint256 public price1CumulativeLast;
    uint256 public kLast;

    uint256 private constant MINIMUM_LIQUIDITY = 1000;
    uint256 private unlocked = 1;

    event Mint(address indexed sender, uint256 amount0, uint256 amount1);
    event Burn(address indexed sender, uint256 amount0, uint256 amount1, address indexed to);
    event Swap(
        address indexed sender,
        uint256 amount0In,
        uint256 amount1In,
        uint256 amount0Out,
        uint256 amount1Out,
        address indexed to
    );
    event Sync(uint256 reserve0, uint256 reserve1);

    modifier lock() {
        require(unlocked == 1, "LOCKED");
        unlocked = 0;
        _;
        unlocked = 1;
    }

    constructor() ERC20("Xaheen LP Token", "XLP") {
        factory = msg.sender;
    }

    function initialize(address _token0, address _token1, address _revenueContract) external {
        require(msg.sender == factory, "FORBIDDEN");
        token0 = _token0;
        token1 = _token1;
        revenueContract = _revenueContract;
    }

    function getReserves() public view returns (uint256 _reserve0, uint256 _reserve1, uint256 _blockTimestampLast) {
        _reserve0 = reserve0;
        _reserve1 = reserve1;
        _blockTimestampLast = blockTimestampLast;
    }

    function _safeTransfer(address token, address to, uint256 value) private {
        (bool success, bytes memory data) = token.call(abi.encodeWithSelector(0xa9059cbb, to, value));
        require(success && (data.length == 0 || abi.decode(data, (bool))), "TRANSFER_FAILED");
    }

    function _update(uint256 balance0, uint256 balance1, uint256 _reserve0, uint256 _reserve1) private {
        require(balance0 <= type(uint112).max && balance1 <= type(uint112).max, "OVERFLOW");
        uint32 blockTimestamp = uint32(block.timestamp % 2**32);
        uint32 timeElapsed = blockTimestamp - uint32(blockTimestampLast);

        if (timeElapsed > 0 && _reserve0 != 0 && _reserve1 != 0) {
            price0CumulativeLast += uint256(_reserve1 / _reserve0) * timeElapsed;
            price1CumulativeLast += uint256(_reserve0 / _reserve1) * timeElapsed;
        }

        reserve0 = balance0;
        reserve1 = balance1;
        blockTimestampLast = blockTimestamp;
        emit Sync(reserve0, reserve1);
    }

    function _mintFee(uint256 _reserve0, uint256 _reserve1) private returns (bool feeOn) {
        address feeTo = revenueContract;
        feeOn = feeTo != address(0);
        uint256 _kLast = kLast;
        if (feeOn) {
            if (_kLast != 0) {
                uint256 rootK = _sqrt(_reserve0 * _reserve1);
                uint256 rootKLast = _sqrt(_kLast);
                if (rootK > rootKLast) {
                    uint256 numerator = totalSupply() * (rootK - rootKLast);
                    uint256 denominator = rootK * 5 + rootKLast;
                    uint256 liquidity = numerator / denominator;
                    if (liquidity > 0) _mint(feeTo, liquidity);
                }
            }
        } else if (_kLast != 0) {
            kLast = 0;
        }
    }

    function mint(address to) external lock nonReentrant returns (uint256 liquidity) {
        (uint256 _reserve0, uint256 _reserve1,) = getReserves();
        uint256 balance0 = IERC20(token0).balanceOf(address(this));
        uint256 balance1 = IERC20(token1).balanceOf(address(this));
        uint256 amount0 = balance0 - _reserve0;
        uint256 amount1 = balance1 - _reserve1;

        bool feeOn = _mintFee(_reserve0, _reserve1);
        uint256 _totalSupply = totalSupply();

        if (_totalSupply == 0) {
            // First liquidity provision - lock MINIMUM_LIQUIDITY forever by minting to this contract
            liquidity = _sqrt(amount0 * amount1) - MINIMUM_LIQUIDITY;
            _mint(address(this), MINIMUM_LIQUIDITY); // Mint to contract instead of address(0)
        } else {
            liquidity = min((amount0 * _totalSupply) / _reserve0, (amount1 * _totalSupply) / _reserve1);
        }

        require(liquidity > 0, "INSUFFICIENT_LIQUIDITY_MINTED");
        _mint(to, liquidity);

        _update(balance0, balance1, _reserve0, _reserve1);
        if (feeOn) kLast = reserve0 * reserve1;

        emit Mint(msg.sender, amount0, amount1);
    }

    function burn(address to) external lock nonReentrant returns (uint256 amount0, uint256 amount1) {
        (uint256 _reserve0, uint256 _reserve1,) = getReserves();
        address _token0 = token0;
        address _token1 = token1;
        uint256 balance0 = IERC20(_token0).balanceOf(address(this));
        uint256 balance1 = IERC20(_token1).balanceOf(address(this));
        uint256 liquidity = balanceOf(address(this));

        bool feeOn = _mintFee(_reserve0, _reserve1);
        uint256 _totalSupply = totalSupply();

        amount0 = (liquidity * balance0) / _totalSupply;
        amount1 = (liquidity * balance1) / _totalSupply;
        require(amount0 > 0 && amount1 > 0, "INSUFFICIENT_LIQUIDITY_BURNED");

        _burn(address(this), liquidity);
        _safeTransfer(_token0, to, amount0);
        _safeTransfer(_token1, to, amount1);

        balance0 = IERC20(_token0).balanceOf(address(this));
        balance1 = IERC20(_token1).balanceOf(address(this));

        _update(balance0, balance1, _reserve0, _reserve1);
        if (feeOn) kLast = reserve0 * reserve1;

        emit Burn(msg.sender, amount0, amount1, to);
    }

    function swap(uint256 amount0Out, uint256 amount1Out, address to, bytes calldata data) external lock nonReentrant {
        require(amount0Out > 0 || amount1Out > 0, "INSUFFICIENT_OUTPUT_AMOUNT");
        (uint256 _reserve0, uint256 _reserve1,) = getReserves();
        require(amount0Out < _reserve0 && amount1Out < _reserve1, "INSUFFICIENT_LIQUIDITY");

        uint256 balance0;
        uint256 balance1;
        {
            address _token0 = token0;
            address _token1 = token1;
            require(to != _token0 && to != _token1, "INVALID_TO");
            if (amount0Out > 0) _safeTransfer(_token0, to, amount0Out);
            if (amount1Out > 0) _safeTransfer(_token1, to, amount1Out);
            balance0 = IERC20(_token0).balanceOf(address(this));
            balance1 = IERC20(_token1).balanceOf(address(this));
        }

        uint256 amount0In = balance0 > _reserve0 - amount0Out ? balance0 - (_reserve0 - amount0Out) : 0;
        uint256 amount1In = balance1 > _reserve1 - amount1Out ? balance1 - (_reserve1 - amount1Out) : 0;
        require(amount0In > 0 || amount1In > 0, "INSUFFICIENT_INPUT_AMOUNT");

        {
            uint256 balance0Adjusted = (balance0 * 1000) - (amount0In * 3); // 0.3% fee
            uint256 balance1Adjusted = (balance1 * 1000) - (amount1In * 3);
            require(balance0Adjusted * balance1Adjusted >= _reserve0 * _reserve1 * (1000**2), "K");

            // Send 2% of fees to XHTRevenue
            if (revenueContract != address(0)) {
                uint256 fee0 = (amount0In * 3) / 1000;
                uint256 fee1 = (amount1In * 3) / 1000;
                uint256 revenueFee = (fee0 + fee1) / 50; // 2% of 0.3% = 0.006%
                if (revenueFee > 0 && address(this).balance >= revenueFee) {
                    try IXHTRevenue(revenueContract).addRevenue{value: revenueFee}() {} catch {}
                }
            }
        }

        _update(balance0, balance1, _reserve0, _reserve1);
        emit Swap(msg.sender, amount0In, amount1In, amount0Out, amount1Out, to);
    }

    function skim(address to) external lock {
        address _token0 = token0;
        address _token1 = token1;
        _safeTransfer(_token0, to, IERC20(_token0).balanceOf(address(this)) - reserve0);
        _safeTransfer(_token1, to, IERC20(_token1).balanceOf(address(this)) - reserve1);
    }

    function sync() external lock {
        _update(IERC20(token0).balanceOf(address(this)), IERC20(token1).balanceOf(address(this)), reserve0, reserve1);
    }

    function _sqrt(uint256 y) internal pure returns (uint256 z) {
        if (y > 3) {
            z = y;
            uint256 x = y / 2 + 1;
            while (x < z) {
                z = x;
                x = (y / x + x) / 2;
            }
        } else if (y != 0) {
            z = 1;
        }
    }

    function min(uint256 x, uint256 y) internal pure returns (uint256 z) {
        z = x < y ? x : y;
    }
}

contracts/dex/XaheenDEXRouter.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "./XaheenDEXFactory.sol";
import "./XaheenDEXPair.sol";
import "./WXHT.sol";

/**
 * @title XaheenDEXRouter
 * @notice Router contract for Xaheen DEX (Uniswap V2 style)
 * @dev Handles all swaps, liquidity addition/removal with support for XHT
 */
contract XaheenDEXRouter {
    address public immutable factory;
    WXHT public immutable wxht;

    modifier ensure(uint256 deadline) {
        require(deadline >= block.timestamp, "EXPIRED");
        _;
    }

    constructor(address _factory, address payable _WXHT) {
        factory = _factory;
        wxht = WXHT(_WXHT);
    }

    receive() external payable {
        assert(msg.sender == address(wxht));
    }

    // ============ Liquidity Functions ============

    function addLiquidity(
        address tokenA,
        address tokenB,
        uint256 amountADesired,
        uint256 amountBDesired,
        uint256 amountAMin,
        uint256 amountBMin,
        address to,
        uint256 deadline
    ) external ensure(deadline) returns (uint256 amountA, uint256 amountB, uint256 liquidity) {
        (amountA, amountB) = _addLiquidity(tokenA, tokenB, amountADesired, amountBDesired, amountAMin, amountBMin);
        address pair = XaheenDEXFactory(factory).getPair(tokenA, tokenB);
        _safeTransferFrom(tokenA, msg.sender, pair, amountA);
        _safeTransferFrom(tokenB, msg.sender, pair, amountB);
        liquidity = XaheenDEXPair(pair).mint(to);
    }

    function addLiquidityXHT(
        address token,
        uint256 amountTokenDesired,
        uint256 amountTokenMin,
        uint256 amountXHTMin,
        address to,
        uint256 deadline
    ) external payable ensure(deadline) returns (uint256 amountToken, uint256 amountXHT, uint256 liquidity) {
        (amountToken, amountXHT) = _addLiquidity(
            token,
            address(wxht),
            amountTokenDesired,
            msg.value,
            amountTokenMin,
            amountXHTMin
        );
        address pair = XaheenDEXFactory(factory).getPair(token, address(wxht));
        _safeTransferFrom(token, msg.sender, pair, amountToken);
        wxht.deposit{value: amountXHT}();
        assert(wxht.transfer(pair, amountXHT));
        liquidity = XaheenDEXPair(pair).mint(to);

        if (msg.value > amountXHT) {
            payable(msg.sender).transfer(msg.value - amountXHT);
        }
    }

    function removeLiquidity(
        address tokenA,
        address tokenB,
        uint256 liquidity,
        uint256 amountAMin,
        uint256 amountBMin,
        address to,
        uint256 deadline
    ) public ensure(deadline) returns (uint256 amountA, uint256 amountB) {
        address pair = XaheenDEXFactory(factory).getPair(tokenA, tokenB);
        IERC20(pair).transferFrom(msg.sender, pair, liquidity);
        (uint256 amount0, uint256 amount1) = XaheenDEXPair(pair).burn(to);
        (address token0,) = sortTokens(tokenA, tokenB);
        (amountA, amountB) = tokenA == token0 ? (amount0, amount1) : (amount1, amount0);
        require(amountA >= amountAMin, "INSUFFICIENT_A_AMOUNT");
        require(amountB >= amountBMin, "INSUFFICIENT_B_AMOUNT");
    }

    function removeLiquidityXHT(
        address token,
        uint256 liquidity,
        uint256 amountTokenMin,
        uint256 amountXHTMin,
        address to,
        uint256 deadline
    ) public ensure(deadline) returns (uint256 amountToken, uint256 amountXHT) {
        (amountToken, amountXHT) = removeLiquidity(
            token,
            address(wxht),
            liquidity,
            amountTokenMin,
            amountXHTMin,
            address(this),
            deadline
        );
        _safeTransfer(token, to, amountToken);
        wxht.withdraw(amountXHT);
        payable(to).transfer(amountXHT);
    }

    // ============ Swap Functions ============

    function swapExactTokensForTokens(
        uint256 amountIn,
        uint256 amountOutMin,
        address[] calldata path,
        address to,
        uint256 deadline
    ) external ensure(deadline) returns (uint256[] memory amounts) {
        amounts = getAmountsOut(amountIn, path);
        require(amounts[amounts.length - 1] >= amountOutMin, "INSUFFICIENT_OUTPUT_AMOUNT");
        _safeTransferFrom(path[0], msg.sender, XaheenDEXFactory(factory).getPair(path[0], path[1]), amounts[0]);
        _swap(amounts, path, to);
    }

    function swapTokensForExactTokens(
        uint256 amountOut,
        uint256 amountInMax,
        address[] calldata path,
        address to,
        uint256 deadline
    ) external ensure(deadline) returns (uint256[] memory amounts) {
        amounts = getAmountsIn(amountOut, path);
        require(amounts[0] <= amountInMax, "EXCESSIVE_INPUT_AMOUNT");
        _safeTransferFrom(path[0], msg.sender, XaheenDEXFactory(factory).getPair(path[0], path[1]), amounts[0]);
        _swap(amounts, path, to);
    }

    function swapExactXHTForTokens(
        uint256 amountOutMin,
        address[] calldata path,
        address to,
        uint256 deadline
    ) external payable ensure(deadline) returns (uint256[] memory amounts) {
        require(path[0] == address(wxht), "INVALID_PATH");
        amounts = getAmountsOut(msg.value, path);
        require(amounts[amounts.length - 1] >= amountOutMin, "INSUFFICIENT_OUTPUT_AMOUNT");
        wxht.deposit{value: amounts[0]}();
        assert(wxht.transfer(XaheenDEXFactory(factory).getPair(path[0], path[1]), amounts[0]));
        _swap(amounts, path, to);
    }

    function swapTokensForExactXHT(
        uint256 amountOut,
        uint256 amountInMax,
        address[] calldata path,
        address to,
        uint256 deadline
    ) external ensure(deadline) returns (uint256[] memory amounts) {
        require(path[path.length - 1] == address(wxht), "INVALID_PATH");
        amounts = getAmountsIn(amountOut, path);
        require(amounts[0] <= amountInMax, "EXCESSIVE_INPUT_AMOUNT");
        _safeTransferFrom(path[0], msg.sender, XaheenDEXFactory(factory).getPair(path[0], path[1]), amounts[0]);
        _swap(amounts, path, address(this));
        wxht.withdraw(amounts[amounts.length - 1]);
        payable(to).transfer(amounts[amounts.length - 1]);
    }

    function swapExactTokensForXHT(
        uint256 amountIn,
        uint256 amountOutMin,
        address[] calldata path,
        address to,
        uint256 deadline
    ) external ensure(deadline) returns (uint256[] memory amounts) {
        require(path[path.length - 1] == address(wxht), "INVALID_PATH");
        amounts = getAmountsOut(amountIn, path);
        require(amounts[amounts.length - 1] >= amountOutMin, "INSUFFICIENT_OUTPUT_AMOUNT");
        _safeTransferFrom(path[0], msg.sender, XaheenDEXFactory(factory).getPair(path[0], path[1]), amounts[0]);
        _swap(amounts, path, address(this));
        wxht.withdraw(amounts[amounts.length - 1]);
        payable(to).transfer(amounts[amounts.length - 1]);
    }

    function swapXHTForExactTokens(
        uint256 amountOut,
        address[] calldata path,
        address to,
        uint256 deadline
    ) external payable ensure(deadline) returns (uint256[] memory amounts) {
        require(path[0] == address(wxht), "INVALID_PATH");
        amounts = getAmountsIn(amountOut, path);
        require(amounts[0] <= msg.value, "EXCESSIVE_INPUT_AMOUNT");
        wxht.deposit{value: amounts[0]}();
        assert(wxht.transfer(XaheenDEXFactory(factory).getPair(path[0], path[1]), amounts[0]));
        _swap(amounts, path, to);

        if (msg.value > amounts[0]) {
            payable(msg.sender).transfer(msg.value - amounts[0]);
        }
    }

    // ============ Internal Functions ============

    function _addLiquidity(
        address tokenA,
        address tokenB,
        uint256 amountADesired,
        uint256 amountBDesired,
        uint256 amountAMin,
        uint256 amountBMin
    ) internal returns (uint256 amountA, uint256 amountB) {
        if (XaheenDEXFactory(factory).getPair(tokenA, tokenB) == address(0)) {
            XaheenDEXFactory(factory).createPair(tokenA, tokenB);
        }

        (uint256 reserveA, uint256 reserveB) = getReserves(tokenA, tokenB);
        if (reserveA == 0 && reserveB == 0) {
            (amountA, amountB) = (amountADesired, amountBDesired);
        } else {
            uint256 amountBOptimal = quote(amountADesired, reserveA, reserveB);
            if (amountBOptimal <= amountBDesired) {
                require(amountBOptimal >= amountBMin, "INSUFFICIENT_B_AMOUNT");
                (amountA, amountB) = (amountADesired, amountBOptimal);
            } else {
                uint256 amountAOptimal = quote(amountBDesired, reserveB, reserveA);
                assert(amountAOptimal <= amountADesired);
                require(amountAOptimal >= amountAMin, "INSUFFICIENT_A_AMOUNT");
                (amountA, amountB) = (amountAOptimal, amountBDesired);
            }
        }
    }

    function _swap(uint256[] memory amounts, address[] memory path, address _to) internal {
        for (uint256 i; i < path.length - 1; i++) {
            (address input, address output) = (path[i], path[i + 1]);
            (address token0,) = sortTokens(input, output);
            uint256 amountOut = amounts[i + 1];
            (uint256 amount0Out, uint256 amount1Out) = input == token0 ? (uint256(0), amountOut) : (amountOut, uint256(0));
            address to = i < path.length - 2 ? XaheenDEXFactory(factory).getPair(output, path[i + 2]) : _to;
            XaheenDEXPair(XaheenDEXFactory(factory).getPair(input, output)).swap(amount0Out, amount1Out, to, new bytes(0));
        }
    }

    function _safeTransferFrom(address token, address from, address to, uint256 value) internal {
        (bool success, bytes memory data) = token.call(abi.encodeWithSelector(0x23b872dd, from, to, value));
        require(success && (data.length == 0 || abi.decode(data, (bool))), "TRANSFER_FROM_FAILED");
    }

    function _safeTransfer(address token, address to, uint256 value) internal {
        (bool success, bytes memory data) = token.call(abi.encodeWithSelector(0xa9059cbb, to, value));
        require(success && (data.length == 0 || abi.decode(data, (bool))), "TRANSFER_FAILED");
    }

    // ============ View Functions ============

    function quote(uint256 amountA, uint256 reserveA, uint256 reserveB) public pure returns (uint256 amountB) {
        require(amountA > 0, "INSUFFICIENT_AMOUNT");
        require(reserveA > 0 && reserveB > 0, "INSUFFICIENT_LIQUIDITY");
        amountB = (amountA * reserveB) / reserveA;
    }

    function getAmountOut(uint256 amountIn, uint256 reserveIn, uint256 reserveOut) public pure returns (uint256 amountOut) {
        require(amountIn > 0, "INSUFFICIENT_INPUT_AMOUNT");
        require(reserveIn > 0 && reserveOut > 0, "INSUFFICIENT_LIQUIDITY");
        uint256 amountInWithFee = amountIn * 997;
        uint256 numerator = amountInWithFee * reserveOut;
        uint256 denominator = (reserveIn * 1000) + amountInWithFee;
        amountOut = numerator / denominator;
    }

    function getAmountIn(uint256 amountOut, uint256 reserveIn, uint256 reserveOut) public pure returns (uint256 amountIn) {
        require(amountOut > 0, "INSUFFICIENT_OUTPUT_AMOUNT");
        require(reserveIn > 0 && reserveOut > 0, "INSUFFICIENT_LIQUIDITY");
        uint256 numerator = reserveIn * amountOut * 1000;
        uint256 denominator = (reserveOut - amountOut) * 997;
        amountIn = (numerator / denominator) + 1;
    }

    function getAmountsOut(uint256 amountIn, address[] memory path) public view returns (uint256[] memory amounts) {
        require(path.length >= 2, "INVALID_PATH");
        amounts = new uint256[](path.length);
        amounts[0] = amountIn;
        for (uint256 i; i < path.length - 1; i++) {
            (uint256 reserveIn, uint256 reserveOut) = getReserves(path[i], path[i + 1]);
            amounts[i + 1] = getAmountOut(amounts[i], reserveIn, reserveOut);
        }
    }

    function getAmountsIn(uint256 amountOut, address[] memory path) public view returns (uint256[] memory amounts) {
        require(path.length >= 2, "INVALID_PATH");
        amounts = new uint256[](path.length);
        amounts[amounts.length - 1] = amountOut;
        for (uint256 i = path.length - 1; i > 0; i--) {
            (uint256 reserveIn, uint256 reserveOut) = getReserves(path[i - 1], path[i]);
            amounts[i - 1] = getAmountIn(amounts[i], reserveIn, reserveOut);
        }
    }

    function getReserves(address tokenA, address tokenB) public view returns (uint256 reserveA, uint256 reserveB) {
        (address token0,) = sortTokens(tokenA, tokenB);
        (uint256 reserve0, uint256 reserve1,) = XaheenDEXPair(XaheenDEXFactory(factory).getPair(tokenA, tokenB)).getReserves();
        (reserveA, reserveB) = tokenA == token0 ? (reserve0, reserve1) : (reserve1, reserve0);
    }

    function sortTokens(address tokenA, address tokenB) internal pure returns (address token0, address token1) {
        require(tokenA != tokenB, "IDENTICAL_ADDRESSES");
        (token0, token1) = tokenA < tokenB ? (tokenA, tokenB) : (tokenB, tokenA);
        require(token0 != address(0), "ZERO_ADDRESS");
    }
}

contracts/factories/CREATE2Factory.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

/**
 * @title CREATE2Factory
 * @dev Factory contract for deploying contracts with deterministic addresses using CREATE2
 * This enables same contract addresses across different chains
 */
contract CREATE2Factory {
    event ContractDeployed(address indexed deployedAddress, bytes32 indexed salt);

    /**
     * @dev Deploys a contract using CREATE2
     * @param bytecode The creation bytecode of the contract to deploy
     * @param salt The salt to use for CREATE2 (determines the address)
     * @return deployedAddress The address of the deployed contract
     */
    function deploy(bytes memory bytecode, bytes32 salt) public returns (address deployedAddress) {
        assembly {
            deployedAddress := create2(0, add(bytecode, 0x20), mload(bytecode), salt)
        }

        require(deployedAddress != address(0), "CREATE2: Failed to deploy contract");

        emit ContractDeployed(deployedAddress, salt);
    }

    /**
     * @dev Computes the address of a contract deployed with CREATE2
     * @param bytecode The creation bytecode of the contract
     * @param salt The salt used for CREATE2
     * @return predictedAddress The predicted address where the contract will be deployed
     */
    function computeAddress(bytes memory bytecode, bytes32 salt) public view returns (address predictedAddress) {
        bytes32 hash = keccak256(
            abi.encodePacked(
                bytes1(0xff),
                address(this),
                salt,
                keccak256(bytecode)
            )
        );

        predictedAddress = address(uint160(uint256(hash)));
    }

    /**
     * @dev Computes the address with a specific factory address (for cross-chain prediction)
     * @param factoryAddress The address of the CREATE2Factory on another chain
     * @param bytecode The creation bytecode of the contract
     * @param salt The salt to use
     * @return predictedAddress The predicted address
     */
    function computeAddressWithFactory(
        address factoryAddress,
        bytes memory bytecode,
        bytes32 salt
    ) public pure returns (address predictedAddress) {
        bytes32 hash = keccak256(
            abi.encodePacked(
                bytes1(0xff),
                factoryAddress,
                salt,
                keccak256(bytecode)
            )
        );

        predictedAddress = address(uint160(uint256(hash)));
    }
}

contracts/MintableBTCBR.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

contract MintableBTCBR {
    string public name = "Bitcoin BR";
    string public symbol = "BTCBR";
    uint8 public decimals = 18;
    uint256 public totalSupply;

    mapping(address => uint256) public balanceOf;
    mapping(address => mapping(address => uint256)) public allowance;

    address public owner;

    event Transfer(address indexed from, address indexed to, uint256 value);
    event Approval(address indexed owner, address indexed spender, uint256 value);
    event Mint(address indexed to, uint256 amount);

    modifier onlyOwner() {
        require(msg.sender == owner, "Not owner");
        _;
    }

    constructor() {
        owner = msg.sender;
    }

    function mint(address to, uint256 amount) external onlyOwner {
        totalSupply += amount;
        balanceOf[to] += amount;
        emit Mint(to, amount);
        emit Transfer(address(0), to, amount);
    }

    function transfer(address to, uint256 amount) external returns (bool) {
        require(balanceOf[msg.sender] >= amount, "Insufficient balance");
        balanceOf[msg.sender] -= amount;
        balanceOf[to] += amount;
        emit Transfer(msg.sender, to, amount);
        return true;
    }

    function approve(address spender, uint256 amount) external returns (bool) {
        allowance[msg.sender][spender] = amount;
        emit Approval(msg.sender, spender, amount);
        return true;
    }

    function transferFrom(address from, address to, uint256 amount) external returns (bool) {
        require(balanceOf[from] >= amount, "Insufficient balance");
        require(allowance[from][msg.sender] >= amount, "Insufficient allowance");

        balanceOf[from] -= amount;
        balanceOf[to] += amount;
        allowance[from][msg.sender] -= amount;

        emit Transfer(from, to, amount);
        return true;
    }
}

contracts/tokenomics/XHTBurnMechanism.so.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/Ownable.sol";

/**
 * @title XHTBurnMechanism
 * @notice Triple burn mechanism for XHT deflationary tokenomics
 * @dev Burns XHT from three sources:
 * 1. 50% of gas fees (velocity sink - more usage = more burn)
 * 2. 10% of validator rewards
 * 3. 5% of bridge fees
 *
 * Expected burn rate: 5-10% annually
 * Minimum supply floor: 100M XHT (10% of original 1B)
 */
contract XHTBurnMechanism is Ownable {

    // ============ State Variables ============

    uint256 public totalBurned;
    uint256 public constant INITIAL_SUPPLY = 1_000_000_000 ether; // 1 billion XHT
    uint256 public constant MINIMUM_SUPPLY = 100_000_000 ether;   // 100 million XHT floor

    uint256 public gasBurnPercentage = 50;      // 50% of gas fees
    uint256 public validatorBurnPercentage = 10; // 10% of validator rewards
    uint256 public bridgeBurnPercentage = 5;     // 5% of bridge fees

    // Velocity sink - increases burn for heavy users
    mapping(address => uint256) public userTransactionCount;

    uint256 public constant BASE_BURN_RATE = 50;     // 50% base
    uint256 public constant POWER_USER_THRESHOLD = 10;
    uint256 public constant HEAVY_USER_THRESHOLD = 100;
    uint256 public constant MAX_BURN_RATE = 80;      // 80% maximum

    address public deadAddress = 0x000000000000000000000000000000000000dEaD;

    // ============ Events ============

    event GasBurned(address indexed user, uint256 amount, uint256 burnRate);
    event ValidatorRewardBurned(address indexed validator, uint256 amount);
    event BridgeFeeBurned(uint256 amount);
    event BurnRatesUpdated(uint256 gasBurn, uint256 validatorBurn, uint256 bridgeBurn);
    event TotalBurnedUpdated(uint256 totalBurned, uint256 remainingSupply);

    // ============ Core Functions ============

    /**
     * @notice Burn portion of gas fees (called by validator after each block)
     * @param user Transaction sender
     * @param gasUsed Amount of gas used
     */
    function burnGasFees(address user, uint256 gasUsed) external payable {
        require(msg.value > 0, "No value sent");

        // Increment user transaction count
        userTransactionCount[user]++;

        // Calculate dynamic burn rate based on user activity
        uint256 burnRate = calculateBurnRate(user);

        // Calculate burn amount
        uint256 burnAmount = (msg.value * burnRate) / 100;

        // Ensure we don't go below minimum supply
        if (getCurrentSupply() - burnAmount < MINIMUM_SUPPLY) {
            burnAmount = getCurrentSupply() - MINIMUM_SUPPLY;
        }

        if (burnAmount > 0) {
            totalBurned += burnAmount;

            // Send to dead address
            (bool success, ) = deadAddress.call{value: burnAmount}("");
            require(success, "Burn failed");

            emit GasBurned(user, burnAmount, burnRate);
            emit TotalBurnedUpdated(totalBurned, getCurrentSupply());
        }

        // Return remaining to validator
        uint256 remaining = msg.value - burnAmount;
        if (remaining > 0) {
            (bool success, ) = msg.sender.call{value: remaining}("");
            require(success, "Refund failed");
        }
    }

    /**
     * @notice Burn portion of validator rewards
     * @param validator Validator address
     */
    function burnValidatorReward(address validator) external payable {
        require(msg.value > 0, "No value sent");

        uint256 burnAmount = (msg.value * validatorBurnPercentage) / 100;

        // Ensure we don't go below minimum supply
        if (getCurrentSupply() - burnAmount < MINIMUM_SUPPLY) {
            burnAmount = getCurrentSupply() - MINIMUM_SUPPLY;
        }

        if (burnAmount > 0) {
            totalBurned += burnAmount;

            (bool success, ) = deadAddress.call{value: burnAmount}("");
            require(success, "Burn failed");

            emit ValidatorRewardBurned(validator, burnAmount);
            emit TotalBurnedUpdated(totalBurned, getCurrentSupply());
        }

        // Return remaining to validator
        uint256 remaining = msg.value - burnAmount;
        if (remaining > 0) {
            (bool success, ) = msg.sender.call{value: remaining}("");
            require(success, "Refund failed");
        }
    }

    /**
     * @notice Burn portion of bridge fees
     */
    function burnBridgeFees() external payable {
        require(msg.value > 0, "No value sent");

        uint256 burnAmount = (msg.value * bridgeBurnPercentage) / 100;

        // Ensure we don't go below minimum supply
        if (getCurrentSupply() - burnAmount < MINIMUM_SUPPLY) {
            burnAmount = getCurrentSupply() - MINIMUM_SUPPLY;
        }

        if (burnAmount > 0) {
            totalBurned += burnAmount;

            (bool success, ) = deadAddress.call{value: burnAmount}("");
            require(success, "Burn failed");

            emit BridgeFeeBurned(burnAmount);
            emit TotalBurnedUpdated(totalBurned, getCurrentSupply());
        }

        // Return remaining to bridge contract
        uint256 remaining = msg.value - burnAmount;
        if (remaining > 0) {
            (bool success, ) = msg.sender.call{value: remaining}("");
            require(success, "Refund failed");
        }
    }

    /**
     * @notice Calculate dynamic burn rate based on user activity (Velocity Sink)
     * @param user User address
     * @return Burn rate percentage (50-80%)
     */
    function calculateBurnRate(address user) public view returns (uint256) {
        uint256 txCount = userTransactionCount[user];

        if (txCount < POWER_USER_THRESHOLD) {
            return BASE_BURN_RATE; // 50%
        } else if (txCount < HEAVY_USER_THRESHOLD) {
            return 60; // Power users burn 60%
        } else if (txCount < 1000) {
            return 70; // Heavy users burn 70%
        } else {
            return MAX_BURN_RATE; // 80% for very heavy users
        }
    }

    /**
     * @notice Get current circulating supply
     * @return Current supply (initial - burned)
     */
    function getCurrentSupply() public view returns (uint256) {
        return INITIAL_SUPPLY - totalBurned;
    }

    /**
     * @notice Get burn percentage (of initial supply)
     * @return Percentage burned (0-100)
     */
    function getBurnPercentage() external view returns (uint256) {
        return (totalBurned * 100) / INITIAL_SUPPLY;
    }

    /**
     * @notice Check if supply is at minimum floor
     * @return True if at floor
     */
    function isAtMinimumSupply() external view returns (bool) {
        return getCurrentSupply() <= MINIMUM_SUPPLY;
    }

    /**
     * @notice Get complete burn statistics
     */
    function getBurnStats() external view returns (
        uint256 _totalBurned,
        uint256 currentSupply,
        uint256 burnPercentage,
        uint256 remainingBurnCapacity,
        bool atFloor
    ) {
        uint256 supply = getCurrentSupply();
        return (
            totalBurned,
            supply,
            (totalBurned * 100) / INITIAL_SUPPLY,
            supply - MINIMUM_SUPPLY,
            supply <= MINIMUM_SUPPLY
        );
    }

    // ============ Admin Functions ============

    /**
     * @notice Update burn percentages
     * @param gasBurn Gas fee burn percentage
     * @param validatorBurn Validator reward burn percentage
     * @param bridgeBurn Bridge fee burn percentage
     */
    function updateBurnRates(
        uint256 gasBurn,
        uint256 validatorBurn,
        uint256 bridgeBurn
    ) external onlyOwner {
        require(gasBurn <= 80, "Gas burn too high");
        require(validatorBurn <= 20, "Validator burn too high");
        require(bridgeBurn <= 10, "Bridge burn too high");

        gasBurnPercentage = gasBurn;
        validatorBurnPercentage = validatorBurn;
        bridgeBurnPercentage = bridgeBurn;

        emit BurnRatesUpdated(gasBurn, validatorBurn, bridgeBurn);
    }

    /**
     * @notice Manual burn (for buyback & burn)
     */
    function manualBurn() external payable onlyOwner {
        require(msg.value > 0, "No value sent");
        require(getCurrentSupply() - msg.value >= MINIMUM_SUPPLY, "Would go below floor");

        totalBurned += msg.value;

        (bool success, ) = deadAddress.call{value: msg.value}("");
        require(success, "Burn failed");

        emit TotalBurnedUpdated(totalBurned, getCurrentSupply());
    }

    // ============ View Functions ============

    /**
     * @notice Get user's transaction count and burn rate
     */
    function getUserBurnInfo(address user) external view returns (
        uint256 txCount,
        uint256 burnRate,
        string memory tier
    ) {
        uint256 count = userTransactionCount[user];
        uint256 rate = calculateBurnRate(user);
        string memory tierName;

        if (count < POWER_USER_THRESHOLD) {
            tierName = "Standard (50%)";
        } else if (count < HEAVY_USER_THRESHOLD) {
            tierName = "Power User (60%)";
        } else if (count < 1000) {
            tierName = "Heavy User (70%)";
        } else {
            tierName = "Ultra User (80%)";
        }

        return (count, rate, tierName);
    }
}

contracts/tokenomics/XHTCharity.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";
import "@openzeppelin/contracts/security/Pausable.sol";

/**
 * @title XHTCharity
 * @notice Transparent charity and donation platform for Xaheen ecosystem
 * @dev Features:
 * - Verified charity organizations
 * - Transparent fund tracking
 * - Recurring donations (monthly/yearly)
 * - Donation matching (corporate/community)
 * - Impact reporting and milestones
 * - Tax receipt generation (metadata)
 * - Zero platform fees for verified charities
 */
contract XHTCharity is Ownable, ReentrancyGuard, Pausable {

    // ============ State Variables ============

    struct Charity {
        uint256 id;
        address wallet;
        string name;
        string description;
        string category;
        string website;
        bool verified;
        bool active;
        uint256 totalReceived;
        uint256 totalWithdrawn;
        uint256 donorCount;
        mapping(address => uint256) donations;
        mapping(address => RecurringDonation) recurring;
    }

    struct RecurringDonation {
        uint256 amount;
        uint256 interval; // seconds between donations (30 days for monthly)
        uint256 lastDonation;
        bool active;
    }

    struct DonationMatch {
        uint256 id;
        address matcher;
        uint256 matchAmount;
        uint256 maxMatch;
        uint256 currentMatch;
        uint256 charityId;
        bool active;
    }

    struct CharityView {
        uint256 id;
        address wallet;
        string name;
        string description;
        string category;
        string website;
        bool verified;
        bool active;
        uint256 totalReceived;
        uint256 totalWithdrawn;
        uint256 donorCount;
        uint256 availableBalance;
    }

    struct ImpactReport {
        uint256 charityId;
        string title;
        string description;
        uint256 amountUsed;
        uint256 beneficiaries;
        string proofUrl;
        uint256 timestamp;
    }

    mapping(uint256 => Charity) public charities;
    uint256 public charityCount;

    mapping(uint256 => DonationMatch) public matches;
    uint256 public matchCount;

    mapping(uint256 => ImpactReport[]) public impactReports;

    uint256 public totalDonations;
    uint256 public totalMatched;

    // ============ Events ============

    event CharityRegistered(
        uint256 indexed charityId,
        address indexed wallet,
        string name
    );
    event CharityVerified(uint256 indexed charityId);
    event DonationMade(
        uint256 indexed charityId,
        address indexed donor,
        uint256 amount,
        bool isRecurring
    );
    event RecurringDonationSetup(
        uint256 indexed charityId,
        address indexed donor,
        uint256 amount,
        uint256 interval
    );
    event RecurringDonationExecuted(
        uint256 indexed charityId,
        address indexed donor,
        uint256 amount
    );
    event DonationMatched(
        uint256 indexed matchId,
        uint256 indexed charityId,
        uint256 amount
    );
    event FundsWithdrawn(
        uint256 indexed charityId,
        address indexed wallet,
        uint256 amount
    );
    event ImpactReportAdded(
        uint256 indexed charityId,
        string title,
        uint256 amountUsed,
        uint256 beneficiaries
    );

    // ============ Core Functions ============

    /**
     * @notice Register a new charity organization
     * @param name Charity name
     * @param description Detailed description
     * @param category Category (health, education, environment, etc.)
     * @param website Official website
     */
    function registerCharity(
        string memory name,
        string memory description,
        string memory category,
        string memory website
    ) external whenNotPaused returns (uint256) {
        require(bytes(name).length > 0, "Name required");

        charityCount++;
        uint256 charityId = charityCount;

        Charity storage charity = charities[charityId];
        charity.id = charityId;
        charity.wallet = msg.sender;
        charity.name = name;
        charity.description = description;
        charity.category = category;
        charity.website = website;
        charity.active = true;

        emit CharityRegistered(charityId, msg.sender, name);
        return charityId;
    }

    /**
     * @notice Make a one-time donation
     * @param charityId Charity ID
     */
    function donate(uint256 charityId) external payable nonReentrant whenNotPaused {
        Charity storage charity = charities[charityId];
        require(charity.active, "Charity not active");
        require(msg.value > 0, "No donation sent");

        // Track new donor
        if (charity.donations[msg.sender] == 0) {
            charity.donorCount++;
        }

        charity.donations[msg.sender] += msg.value;
        charity.totalReceived += msg.value;
        totalDonations += msg.value;

        emit DonationMade(charityId, msg.sender, msg.value, false);

        // Check for active donation matches
        _applyMatching(charityId, msg.value);
    }

    /**
     * @notice Setup recurring donation
     * @param charityId Charity ID
     * @param amount Donation amount per interval
     * @param interval Seconds between donations (30 days = 2592000)
     */
    function setupRecurringDonation(
        uint256 charityId,
        uint256 amount,
        uint256 interval
    ) external payable nonReentrant whenNotPaused {
        Charity storage charity = charities[charityId];
        require(charity.active, "Charity not active");
        require(amount > 0, "Amount must be positive");
        require(interval >= 1 days, "Interval too short");
        require(msg.value >= amount, "Insufficient initial payment");

        RecurringDonation storage recurring = charity.recurring[msg.sender];
        recurring.amount = amount;
        recurring.interval = interval;
        recurring.lastDonation = block.timestamp;
        recurring.active = true;

        // Process initial donation
        if (charity.donations[msg.sender] == 0) {
            charity.donorCount++;
        }

        charity.donations[msg.sender] += amount;
        charity.totalReceived += amount;
        totalDonations += amount;

        emit RecurringDonationSetup(charityId, msg.sender, amount, interval);
        emit DonationMade(charityId, msg.sender, amount, true);

        // Refund excess
        if (msg.value > amount) {
            (bool success, ) = msg.sender.call{value: msg.value - amount}("");
            require(success, "Refund failed");
        }
    }

    /**
     * @notice Execute recurring donation (called by donor or automation)
     * @param charityId Charity ID
     */
    function executeRecurringDonation(uint256 charityId) external payable nonReentrant {
        Charity storage charity = charities[charityId];
        RecurringDonation storage recurring = charity.recurring[msg.sender];

        require(recurring.active, "No active recurring donation");
        require(
            block.timestamp >= recurring.lastDonation + recurring.interval,
            "Too early"
        );
        require(msg.value >= recurring.amount, "Insufficient payment");

        recurring.lastDonation = block.timestamp;

        charity.donations[msg.sender] += recurring.amount;
        charity.totalReceived += recurring.amount;
        totalDonations += recurring.amount;

        emit RecurringDonationExecuted(charityId, msg.sender, recurring.amount);

        // Refund excess
        if (msg.value > recurring.amount) {
            (bool success, ) = msg.sender.call{value: msg.value - recurring.amount}("");
            require(success, "Refund failed");
        }
    }

    /**
     * @notice Cancel recurring donation
     * @param charityId Charity ID
     */
    function cancelRecurringDonation(uint256 charityId) external {
        Charity storage charity = charities[charityId];
        RecurringDonation storage recurring = charity.recurring[msg.sender];
        require(recurring.active, "No active recurring donation");

        recurring.active = false;
    }

    /**
     * @notice Create donation matching campaign
     * @param charityId Charity to match donations for
     * @param maxMatch Maximum total match amount
     */
    function createDonationMatch(
        uint256 charityId,
        uint256 maxMatch
    ) external payable nonReentrant {
        require(charities[charityId].active, "Charity not active");
        require(msg.value >= maxMatch, "Insufficient funding");

        matchCount++;
        uint256 matchId = matchCount;

        DonationMatch storage donationMatch = matches[matchId];
        donationMatch.id = matchId;
        donationMatch.matcher = msg.sender;
        donationMatch.matchAmount = msg.value;
        donationMatch.maxMatch = maxMatch;
        donationMatch.charityId = charityId;
        donationMatch.active = true;
    }

    /**
     * @notice Internal function to apply matching
     */
    function _applyMatching(uint256 charityId, uint256 amount) internal {
        // Find active matches for this charity
        for (uint256 i = 1; i <= matchCount; i++) {
            DonationMatch storage donationMatch = matches[i];
            if (donationMatch.charityId == charityId &&
                donationMatch.active &&
                donationMatch.currentMatch < donationMatch.maxMatch) {

                uint256 matchAmount = amount; // 1:1 matching
                uint256 remaining = donationMatch.maxMatch - donationMatch.currentMatch;

                if (matchAmount > remaining) {
                    matchAmount = remaining;
                }

                if (matchAmount > 0) {
                    donationMatch.currentMatch += matchAmount;
                    charities[charityId].totalReceived += matchAmount;
                    totalMatched += matchAmount;

                    emit DonationMatched(i, charityId, matchAmount);

                    if (donationMatch.currentMatch >= donationMatch.maxMatch) {
                        donationMatch.active = false;
                    }
                }
            }
        }
    }

    /**
     * @notice Withdraw funds (charity wallet only)
     * @param charityId Charity ID
     * @param amount Amount to withdraw
     */
    function withdrawFunds(uint256 charityId, uint256 amount) external nonReentrant {
        Charity storage charity = charities[charityId];
        require(msg.sender == charity.wallet, "Not charity wallet");
        require(charity.verified, "Charity not verified");

        uint256 available = charity.totalReceived - charity.totalWithdrawn;
        require(amount <= available, "Insufficient balance");

        charity.totalWithdrawn += amount;

        (bool success, ) = charity.wallet.call{value: amount}("");
        require(success, "Transfer failed");

        emit FundsWithdrawn(charityId, charity.wallet, amount);
    }

    /**
     * @notice Add impact report
     * @param charityId Charity ID
     * @param title Report title
     * @param description Detailed impact description
     * @param amountUsed Amount of donations used
     * @param beneficiaries Number of people/entities helped
     * @param proofUrl URL to proof/documentation
     */
    function addImpactReport(
        uint256 charityId,
        string memory title,
        string memory description,
        uint256 amountUsed,
        uint256 beneficiaries,
        string memory proofUrl
    ) external {
        Charity storage charity = charities[charityId];
        require(msg.sender == charity.wallet, "Not charity wallet");

        impactReports[charityId].push(ImpactReport({
            charityId: charityId,
            title: title,
            description: description,
            amountUsed: amountUsed,
            beneficiaries: beneficiaries,
            proofUrl: proofUrl,
            timestamp: block.timestamp
        }));

        emit ImpactReportAdded(charityId, title, amountUsed, beneficiaries);
    }

    // ============ View Functions ============

    /**
     * @notice Get charity details
     */
    function getCharity(uint256 charityId) external view returns (CharityView memory) {
        Charity storage charity = charities[charityId];
        return CharityView({
            id: charity.id,
            wallet: charity.wallet,
            name: charity.name,
            description: charity.description,
            category: charity.category,
            website: charity.website,
            verified: charity.verified,
            active: charity.active,
            totalReceived: charity.totalReceived,
            totalWithdrawn: charity.totalWithdrawn,
            donorCount: charity.donorCount,
            availableBalance: charity.totalReceived - charity.totalWithdrawn
        });
    }

    /**
     * @notice Get user's total donations to a charity
     */
    function getUserDonations(uint256 charityId, address user) external view returns (uint256) {
        return charities[charityId].donations[user];
    }

    /**
     * @notice Get user's recurring donation info
     */
    function getRecurringDonation(uint256 charityId, address user) external view returns (
        uint256 amount,
        uint256 interval,
        uint256 lastDonation,
        uint256 nextDonation,
        bool active
    ) {
        RecurringDonation memory recurring = charities[charityId].recurring[user];
        uint256 next = recurring.active ? recurring.lastDonation + recurring.interval : 0;
        return (
            recurring.amount,
            recurring.interval,
            recurring.lastDonation,
            next,
            recurring.active
        );
    }

    /**
     * @notice Get impact reports for charity
     */
    function getImpactReports(uint256 charityId) external view returns (ImpactReport[] memory) {
        return impactReports[charityId];
    }

    /**
     * @notice Get platform statistics
     */
    function getPlatformStats() external view returns (
        uint256 totalCharities,
        uint256 verifiedCharities,
        uint256 _totalDonations,
        uint256 _totalMatched
    ) {
        uint256 verified = 0;
        for (uint256 i = 1; i <= charityCount; i++) {
            if (charities[i].verified) verified++;
        }

        return (charityCount, verified, totalDonations, totalMatched);
    }

    // ============ Admin Functions ============

    /**
     * @notice Verify a charity (owner only)
     */
    function verifyCharity(uint256 charityId) external onlyOwner {
        charities[charityId].verified = true;
        emit CharityVerified(charityId);
    }

    /**
     * @notice Deactivate charity (owner or charity wallet)
     */
    function deactivateCharity(uint256 charityId) external {
        Charity storage charity = charities[charityId];
        require(
            msg.sender == owner() || msg.sender == charity.wallet,
            "Not authorized"
        );
        charity.active = false;
    }

    /**
     * @notice Emergency pause
     */
    function pause() external onlyOwner {
        _pause();
    }

    /**
     * @notice Unpause
     */
    function unpause() external onlyOwner {
        _unpause();
    }
}

contracts/tokenomics/XHTCrowdfunding.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";
import "@openzeppelin/contracts/security/Pausable.sol";

/**
 * @title XHTCrowdfunding
 * @notice Decentralized crowdfunding platform for Xaheen ecosystem
 * @dev Features:
 * - All-or-nothing funding (like Kickstarter)
 * - Flexible funding (keep what you raise)
 * - Milestone-based fund release
 * - Backer refunds if goals not met
 * - Platform fee (2% on successful campaigns)
 * - KYC verification for large campaigns
 */
contract XHTCrowdfunding is Ownable, ReentrancyGuard, Pausable {

    // ============ State Variables ============

    struct Campaign {
        uint256 id;
        address creator;
        string title;
        string description;
        string category;
        uint256 goalAmount;
        uint256 raisedAmount;
        uint256 startTime;
        uint256 endTime;
        bool isFlexible;        // Flexible funding (keep raised) vs all-or-nothing
        bool goalReached;
        bool fundsWithdrawn;
        bool canceled;
        uint256 milestoneCount;
        mapping(uint256 => Milestone) milestones;
        mapping(address => uint256) contributions;
        address[] contributors;
    }

    struct Milestone {
        string description;
        uint256 amount;
        bool released;
        uint256 approvalCount;
        mapping(address => bool) approvals;
    }

    struct CampaignView {
        uint256 id;
        address creator;
        string title;
        string description;
        string category;
        uint256 goalAmount;
        uint256 raisedAmount;
        uint256 startTime;
        uint256 endTime;
        bool isFlexible;
        bool goalReached;
        bool fundsWithdrawn;
        bool canceled;
        uint256 milestoneCount;
        uint256 contributorCount;
    }

    mapping(uint256 => Campaign) public campaigns;
    uint256 public campaignCount;

    uint256 public constant PLATFORM_FEE_PERCENTAGE = 2; // 2% fee
    uint256 public constant MIN_CAMPAIGN_DURATION = 7 days;
    uint256 public constant MAX_CAMPAIGN_DURATION = 90 days;
    uint256 public constant MIN_GOAL = 100 ether; // 100 XHT minimum
    uint256 public constant MAX_GOAL = 1_000_000 ether; // 1M XHT maximum

    address public feeCollector;
    uint256 public totalFeesCollected;

    // ============ Events ============

    event CampaignCreated(
        uint256 indexed campaignId,
        address indexed creator,
        string title,
        uint256 goalAmount,
        bool isFlexible
    );
    event ContributionMade(
        uint256 indexed campaignId,
        address indexed contributor,
        uint256 amount
    );
    event CampaignGoalReached(uint256 indexed campaignId, uint256 totalRaised);
    event FundsWithdrawn(uint256 indexed campaignId, address indexed creator, uint256 amount);
    event RefundIssued(uint256 indexed campaignId, address indexed contributor, uint256 amount);
    event CampaignCanceled(uint256 indexed campaignId);
    event MilestoneCreated(uint256 indexed campaignId, uint256 milestoneId, uint256 amount);
    event MilestoneApproved(uint256 indexed campaignId, uint256 milestoneId, address approver);
    event MilestoneReleased(uint256 indexed campaignId, uint256 milestoneId, uint256 amount);

    // ============ Constructor ============

    constructor(address _feeCollector) {
        feeCollector = _feeCollector;
    }

    // ============ Core Functions ============

    /**
     * @notice Create a new crowdfunding campaign
     * @param title Campaign title
     * @param description Detailed description
     * @param category Campaign category (tech, art, charity, etc.)
     * @param goalAmount Funding goal in XHT
     * @param duration Campaign duration in seconds
     * @param isFlexible True for flexible funding, false for all-or-nothing
     */
    function createCampaign(
        string memory title,
        string memory description,
        string memory category,
        uint256 goalAmount,
        uint256 duration,
        bool isFlexible
    ) external whenNotPaused returns (uint256) {
        require(goalAmount >= MIN_GOAL, "Goal too low");
        require(goalAmount <= MAX_GOAL, "Goal too high");
        require(duration >= MIN_CAMPAIGN_DURATION, "Duration too short");
        require(duration <= MAX_CAMPAIGN_DURATION, "Duration too long");
        require(bytes(title).length > 0, "Title required");

        campaignCount++;
        uint256 campaignId = campaignCount;

        Campaign storage campaign = campaigns[campaignId];
        campaign.id = campaignId;
        campaign.creator = msg.sender;
        campaign.title = title;
        campaign.description = description;
        campaign.category = category;
        campaign.goalAmount = goalAmount;
        campaign.startTime = block.timestamp;
        campaign.endTime = block.timestamp + duration;
        campaign.isFlexible = isFlexible;

        emit CampaignCreated(campaignId, msg.sender, title, goalAmount, isFlexible);
        return campaignId;
    }

    /**
     * @notice Contribute to a campaign
     * @param campaignId Campaign ID
     */
    function contribute(uint256 campaignId) external payable nonReentrant whenNotPaused {
        Campaign storage campaign = campaigns[campaignId];
        require(msg.value > 0, "No contribution sent");
        require(block.timestamp >= campaign.startTime, "Campaign not started");
        require(block.timestamp <= campaign.endTime, "Campaign ended");
        require(!campaign.canceled, "Campaign canceled");

        // Track new contributor
        if (campaign.contributions[msg.sender] == 0) {
            campaign.contributors.push(msg.sender);
        }

        campaign.contributions[msg.sender] += msg.value;
        campaign.raisedAmount += msg.value;

        emit ContributionMade(campaignId, msg.sender, msg.value);

        // Check if goal reached
        if (!campaign.goalReached && campaign.raisedAmount >= campaign.goalAmount) {
            campaign.goalReached = true;
            emit CampaignGoalReached(campaignId, campaign.raisedAmount);
        }
    }

    /**
     * @notice Withdraw funds from successful campaign
     * @param campaignId Campaign ID
     */
    function withdrawFunds(uint256 campaignId) external nonReentrant {
        Campaign storage campaign = campaigns[campaignId];
        require(msg.sender == campaign.creator, "Not campaign creator");
        require(block.timestamp > campaign.endTime, "Campaign still active");
        require(!campaign.fundsWithdrawn, "Funds already withdrawn");
        require(!campaign.canceled, "Campaign canceled");

        // Check if withdrawal allowed
        if (!campaign.isFlexible) {
            require(campaign.goalReached, "Goal not reached");
        }

        campaign.fundsWithdrawn = true;

        uint256 amount = campaign.raisedAmount;
        uint256 fee = (amount * PLATFORM_FEE_PERCENTAGE) / 100;
        uint256 creatorAmount = amount - fee;

        // Send fee to collector
        if (fee > 0) {
            (bool feeSuccess, ) = feeCollector.call{value: fee}("");
            require(feeSuccess, "Fee transfer failed");
            totalFeesCollected += fee;
        }

        // Send remaining to creator
        (bool success, ) = campaign.creator.call{value: creatorAmount}("");
        require(success, "Transfer failed");

        emit FundsWithdrawn(campaignId, campaign.creator, creatorAmount);
    }

    /**
     * @notice Request refund for failed campaign
     * @param campaignId Campaign ID
     */
    function requestRefund(uint256 campaignId) external nonReentrant {
        Campaign storage campaign = campaigns[campaignId];
        require(block.timestamp > campaign.endTime, "Campaign still active");
        require(!campaign.isFlexible, "Flexible funding campaign");
        require(!campaign.goalReached, "Goal was reached");
        require(!campaign.fundsWithdrawn, "Funds already withdrawn");

        uint256 contribution = campaign.contributions[msg.sender];
        require(contribution > 0, "No contribution found");

        campaign.contributions[msg.sender] = 0;
        campaign.raisedAmount -= contribution;

        (bool success, ) = msg.sender.call{value: contribution}("");
        require(success, "Refund failed");

        emit RefundIssued(campaignId, msg.sender, contribution);
    }

    /**
     * @notice Cancel campaign (creator only, before end)
     * @param campaignId Campaign ID
     */
    function cancelCampaign(uint256 campaignId) external {
        Campaign storage campaign = campaigns[campaignId];
        require(msg.sender == campaign.creator || msg.sender == owner(), "Not authorized");
        require(block.timestamp <= campaign.endTime, "Campaign ended");
        require(!campaign.fundsWithdrawn, "Funds already withdrawn");
        require(!campaign.canceled, "Already canceled");

        campaign.canceled = true;
        emit CampaignCanceled(campaignId);
    }

    /**
     * @notice Add milestone to campaign
     * @param campaignId Campaign ID
     * @param description Milestone description
     * @param amount Amount to release for this milestone
     */
    function addMilestone(
        uint256 campaignId,
        string memory description,
        uint256 amount
    ) external {
        Campaign storage campaign = campaigns[campaignId];
        require(msg.sender == campaign.creator, "Not campaign creator");
        require(block.timestamp <= campaign.endTime, "Campaign ended");

        uint256 milestoneId = campaign.milestoneCount++;
        Milestone storage milestone = campaign.milestones[milestoneId];
        milestone.description = description;
        milestone.amount = amount;

        emit MilestoneCreated(campaignId, milestoneId, amount);
    }

    /**
     * @notice Approve milestone completion (backers only)
     * @param campaignId Campaign ID
     * @param milestoneId Milestone ID
     */
    function approveMilestone(uint256 campaignId, uint256 milestoneId) external {
        Campaign storage campaign = campaigns[campaignId];
        require(campaign.contributions[msg.sender] > 0, "Not a contributor");

        Milestone storage milestone = campaign.milestones[milestoneId];
        require(!milestone.released, "Already released");
        require(!milestone.approvals[msg.sender], "Already approved");

        milestone.approvals[msg.sender] = true;
        milestone.approvalCount++;

        emit MilestoneApproved(campaignId, milestoneId, msg.sender);
    }

    // ============ View Functions ============

    /**
     * @notice Get campaign details
     */
    function getCampaign(uint256 campaignId) external view returns (CampaignView memory) {
        Campaign storage campaign = campaigns[campaignId];
        return CampaignView({
            id: campaign.id,
            creator: campaign.creator,
            title: campaign.title,
            description: campaign.description,
            category: campaign.category,
            goalAmount: campaign.goalAmount,
            raisedAmount: campaign.raisedAmount,
            startTime: campaign.startTime,
            endTime: campaign.endTime,
            isFlexible: campaign.isFlexible,
            goalReached: campaign.goalReached,
            fundsWithdrawn: campaign.fundsWithdrawn,
            canceled: campaign.canceled,
            milestoneCount: campaign.milestoneCount,
            contributorCount: campaign.contributors.length
        });
    }

    /**
     * @notice Get user's contribution to a campaign
     */
    function getUserContribution(uint256 campaignId, address user) external view returns (uint256) {
        return campaigns[campaignId].contributions[user];
    }

    /**
     * @notice Get campaign progress percentage
     */
    function getCampaignProgress(uint256 campaignId) external view returns (uint256) {
        Campaign storage campaign = campaigns[campaignId];
        if (campaign.goalAmount == 0) return 0;
        return (campaign.raisedAmount * 100) / campaign.goalAmount;
    }

    /**
     * @notice Check if campaign is active
     */
    function isCampaignActive(uint256 campaignId) external view returns (bool) {
        Campaign storage campaign = campaigns[campaignId];
        return block.timestamp >= campaign.startTime &&
               block.timestamp <= campaign.endTime &&
               !campaign.canceled;
    }

    // ============ Admin Functions ============

    /**
     * @notice Update fee collector address
     */
    function updateFeeCollector(address _feeCollector) external onlyOwner {
        feeCollector = _feeCollector;
    }

    /**
     * @notice Emergency pause
     */
    function pause() external onlyOwner {
        _pause();
    }

    /**
     * @notice Unpause
     */
    function unpause() external onlyOwner {
        _unpause();
    }
}

contracts/tokenomics/XHTGovernance.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";

interface IXHTStaking {
    function getVotingPower(address user) external view returns (uint256);
}

/**
 * @title XHTGovernance
 * @notice Decentralized governance for Xaheen Chain with voting power from staking
 * @dev Features:
 * - Proposal creation and voting
 * - Voting power based on staked XHT (from XHTStaking)
 * - Timelock for executed proposals (48 hours)
 * - Treasury management
 * - Parameter updates (fees, limits, etc.)
 */
contract XHTGovernance is Ownable, ReentrancyGuard {

    // ============ State Variables ============

    IXHTStaking public stakingContract;

    struct Proposal {
        uint256 id;
        address proposer;
        string title;
        string description;
        uint256 forVotes;
        uint256 againstVotes;
        uint256 startTime;
        uint256 endTime;
        bool executed;
        bool canceled;
        ProposalType proposalType;
        bytes executionData;
    }

    enum ProposalType {
        ParameterChange,    // Change protocol parameters
        TreasurySpend,      // Spend from treasury
        ContractUpgrade,    // Upgrade contracts
        ValidatorChange,    // Add/remove validators
        EmergencyAction     // Emergency response
    }

    enum VoteChoice {
        Against,
        For,
        Abstain
    }

    mapping(uint256 => Proposal) public proposals;
    mapping(uint256 => mapping(address => bool)) public hasVoted;
    mapping(uint256 => mapping(address => VoteChoice)) public votes;

    uint256 public proposalCount;
    uint256 public constant VOTING_PERIOD = 7 days;
    uint256 public constant TIMELOCK_PERIOD = 2 days;
    uint256 public constant MIN_VOTING_POWER = 10_000 ether; // 10,000 XHT to propose
    uint256 public constant QUORUM_PERCENTAGE = 10; // 10% of total staking
    uint256 public treasury;

    // ============ Events ============

    event ProposalCreated(
        uint256 indexed proposalId,
        address indexed proposer,
        string title,
        ProposalType proposalType
    );
    event VoteCast(
        uint256 indexed proposalId,
        address indexed voter,
        VoteChoice choice,
        uint256 votingPower
    );
    event ProposalExecuted(uint256 indexed proposalId);
    event ProposalCanceled(uint256 indexed proposalId);
    event TreasuryDeposit(address indexed from, uint256 amount);

    // ============ Constructor ============

    constructor(address _stakingContract) {
        stakingContract = IXHTStaking(_stakingContract);
    }

    // ============ Core Functions ============

    /**
     * @notice Create a new governance proposal
     * @param title Proposal title
     * @param description Detailed description
     * @param proposalType Type of proposal
     * @param executionData Encoded function call data
     */
    function createProposal(
        string memory title,
        string memory description,
        ProposalType proposalType,
        bytes memory executionData
    ) external returns (uint256) {
        uint256 votingPower = stakingContract.getVotingPower(msg.sender);
        require(votingPower >= MIN_VOTING_POWER, "Insufficient voting power");

        proposalCount++;
        uint256 proposalId = proposalCount;

        proposals[proposalId] = Proposal({
            id: proposalId,
            proposer: msg.sender,
            title: title,
            description: description,
            forVotes: 0,
            againstVotes: 0,
            startTime: block.timestamp,
            endTime: block.timestamp + VOTING_PERIOD,
            executed: false,
            canceled: false,
            proposalType: proposalType,
            executionData: executionData
        });

        emit ProposalCreated(proposalId, msg.sender, title, proposalType);
        return proposalId;
    }

    /**
     * @notice Cast a vote on a proposal
     * @param proposalId Proposal ID
     * @param choice Vote choice (Against, For, Abstain)
     */
    function castVote(uint256 proposalId, VoteChoice choice) external nonReentrant {
        Proposal storage proposal = proposals[proposalId];
        require(block.timestamp <= proposal.endTime, "Voting ended");
        require(!proposal.canceled, "Proposal canceled");
        require(!hasVoted[proposalId][msg.sender], "Already voted");

        uint256 votingPower = stakingContract.getVotingPower(msg.sender);
        require(votingPower > 0, "No voting power");

        hasVoted[proposalId][msg.sender] = true;
        votes[proposalId][msg.sender] = choice;

        if (choice == VoteChoice.For) {
            proposal.forVotes += votingPower;
        } else if (choice == VoteChoice.Against) {
            proposal.againstVotes += votingPower;
        }

        emit VoteCast(proposalId, msg.sender, choice, votingPower);
    }

    /**
     * @notice Execute a passed proposal after timelock
     * @param proposalId Proposal ID
     */
    function executeProposal(uint256 proposalId) external nonReentrant {
        Proposal storage proposal = proposals[proposalId];

        require(block.timestamp > proposal.endTime, "Voting not ended");
        require(block.timestamp >= proposal.endTime + TIMELOCK_PERIOD, "Timelock active");
        require(!proposal.executed, "Already executed");
        require(!proposal.canceled, "Proposal canceled");
        require(proposal.forVotes > proposal.againstVotes, "Proposal failed");
        require(hasReachedQuorum(proposalId), "Quorum not reached");

        proposal.executed = true;

        // Execute proposal based on type
        if (proposal.proposalType == ProposalType.TreasurySpend) {
            _executeTreasurySpend(proposal.executionData);
        }
        // Other types can be implemented as needed

        emit ProposalExecuted(proposalId);
    }

    /**
     * @notice Cancel a proposal (only proposer or owner)
     * @param proposalId Proposal ID
     */
    function cancelProposal(uint256 proposalId) external {
        Proposal storage proposal = proposals[proposalId];
        require(
            msg.sender == proposal.proposer || msg.sender == owner(),
            "Not authorized"
        );
        require(!proposal.executed, "Already executed");
        require(!proposal.canceled, "Already canceled");

        proposal.canceled = true;
        emit ProposalCanceled(proposalId);
    }

    /**
     * @notice Check if proposal reached quorum
     * @param proposalId Proposal ID
     * @return True if quorum reached
     */
    function hasReachedQuorum(uint256 proposalId) public view returns (bool) {
        Proposal memory proposal = proposals[proposalId];
        uint256 totalVotes = proposal.forVotes + proposal.againstVotes;

        // For simplicity, using a fixed quorum threshold
        // In production, this should check against total staked supply
        return totalVotes >= 100_000 ether; // 100,000 XHT voting power
    }

    /**
     * @notice Get proposal status
     * @param proposalId Proposal ID
     */
    function getProposalStatus(uint256 proposalId) external view returns (
        bool active,
        bool passed,
        bool executed,
        bool canExecute
    ) {
        Proposal memory proposal = proposals[proposalId];

        active = block.timestamp <= proposal.endTime && !proposal.canceled;
        passed = proposal.forVotes > proposal.againstVotes && hasReachedQuorum(proposalId);
        executed = proposal.executed;
        canExecute = passed &&
                     block.timestamp > proposal.endTime + TIMELOCK_PERIOD &&
                     !proposal.executed &&
                     !proposal.canceled;

        return (active, passed, executed, canExecute);
    }

    // ============ Treasury Functions ============

    /**
     * @notice Deposit to treasury
     */
    function depositToTreasury() external payable {
        treasury += msg.value;
        emit TreasuryDeposit(msg.sender, msg.value);
    }

    /**
     * @notice Execute treasury spend (internal)
     * @param data Encoded recipient and amount
     */
    function _executeTreasurySpend(bytes memory data) internal {
        (address recipient, uint256 amount) = abi.decode(data, (address, uint256));
        require(treasury >= amount, "Insufficient treasury");

        treasury -= amount;
        (bool success, ) = recipient.call{value: amount}("");
        require(success, "Transfer failed");
    }

    /**
     * @notice Get treasury balance
     */
    function getTreasuryBalance() external view returns (uint256) {
        return treasury;
    }

    // ============ View Functions ============

    /**
     * @notice Get proposal details
     */
    function getProposal(uint256 proposalId) external view returns (
        address proposer,
        string memory title,
        string memory description,
        uint256 forVotes,
        uint256 againstVotes,
        uint256 endTime,
        bool executed,
        bool canceled,
        ProposalType proposalType
    ) {
        Proposal memory proposal = proposals[proposalId];
        return (
            proposal.proposer,
            proposal.title,
            proposal.description,
            proposal.forVotes,
            proposal.againstVotes,
            proposal.endTime,
            proposal.executed,
            proposal.canceled,
            proposal.proposalType
        );
    }

    /**
     * @notice Get user's vote on a proposal
     */
    function getUserVote(uint256 proposalId, address user) external view returns (
        bool voted,
        VoteChoice choice
    ) {
        return (hasVoted[proposalId][user], votes[proposalId][user]);
    }

    /**
     * @notice Get voting statistics
     */
    function getVotingStats(uint256 proposalId) external view returns (
        uint256 totalVotes,
        uint256 forPercentage,
        uint256 againstPercentage,
        bool quorumReached
    ) {
        Proposal memory proposal = proposals[proposalId];
        uint256 total = proposal.forVotes + proposal.againstVotes;

        uint256 forPct = total > 0 ? (proposal.forVotes * 100) / total : 0;
        uint256 againstPct = total > 0 ? (proposal.againstVotes * 100) / total : 0;

        return (total, forPct, againstPct, hasReachedQuorum(proposalId));
    }

    // ============ Admin Functions ============

    /**
     * @notice Update staking contract address
     */
    function updateStakingContract(address _stakingContract) external onlyOwner {
        stakingContract = IXHTStaking(_stakingContract);
    }

    /**
     * @notice Emergency withdrawal (owner only)
     */
    function emergencyWithdraw() external onlyOwner {
        uint256 balance = address(this).balance;
        (bool success, ) = owner().call{value: balance}("");
        require(success, "Transfer failed");
    }

    // ============ Receive Function ============

    receive() external payable {
        treasury += msg.value;
        emit TreasuryDeposit(msg.sender, msg.value);
    }
}

contracts/tokenomics/XHTRevenue.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";

interface IXHTStaking {
    function totalStaked() external view returns (uint256);
    function stakes(address user) external view returns (
        uint256 amount,
        uint256 startTime,
        uint256 lockPeriod,
        uint256 lastRewardTime,
        uint256 accumulatedRewards,
        bool isValidator
    );
}

interface IXHTBurnMechanism {
    function burnBridgeFees() external payable;
}

/**
 * @title XHTRevenue
 * @notice Revenue collection and distribution for Xaheen ecosystem
 * @dev Collects fees from:
 * - Bridge transfers (0.1-0.2%)
 * - DEX swaps (0.3%)
 * - NFT marketplace (2.5%)
 * - Premium services
 *
 * Distribution:
 * - 50% to stakers (proportional to stake)
 * - 30% to validators
 * - 10% burned
 * - 10% to treasury
 */
contract XHTRevenue is Ownable, ReentrancyGuard {

    // ============ State Variables ============

    IXHTStaking public stakingContract;
    IXHTBurnMechanism public burnContract;
    address public treasuryAddress;

    struct RevenueStats {
        uint256 totalCollected;
        uint256 distributedToStakers;
        uint256 distributedToValidators;
        uint256 burned;
        uint256 toTreasury;
    }

    RevenueStats public stats;

    mapping(address => bool) public isValidator;
    mapping(address => uint256) public validatorRewards;
    mapping(address => uint256) public stakerRewards;

    uint256 public pendingStakerPool;
    uint256 public pendingValidatorPool;

    // Distribution percentages
    uint256 public constant STAKERS_PERCENTAGE = 50;
    uint256 public constant VALIDATORS_PERCENTAGE = 30;
    uint256 public constant BURN_PERCENTAGE = 10;
    uint256 public constant TREASURY_PERCENTAGE = 10;

    // Minimum distribution threshold (prevents gas waste on small amounts)
    uint256 public constant MIN_DISTRIBUTION_AMOUNT = 1 ether;

    // ============ Events ============

    event RevenueReceived(address indexed from, uint256 amount, string source);
    event RevenueDistributed(
        uint256 toStakers,
        uint256 toValidators,
        uint256 burned,
        uint256 toTreasury
    );
    event StakerRewardClaimed(address indexed staker, uint256 amount);
    event ValidatorRewardClaimed(address indexed validator, uint256 amount);
    event ValidatorAdded(address indexed validator);
    event ValidatorRemoved(address indexed validator);

    // ============ Constructor ============

    constructor(
        address _stakingContract,
        address _burnContract,
        address _treasuryAddress
    ) {
        stakingContract = IXHTStaking(_stakingContract);
        burnContract = IXHTBurnMechanism(_burnContract);
        treasuryAddress = _treasuryAddress;
    }

    // ============ Core Functions ============

    /**
     * @notice Collect revenue from various sources
     * @param source Description of revenue source (bridge, dex, nft, etc.)
     */
    function collectRevenue(string memory source) external payable {
        require(msg.value > 0, "No revenue sent");

        stats.totalCollected += msg.value;

        // Split revenue according to percentages
        uint256 toStakers = (msg.value * STAKERS_PERCENTAGE) / 100;
        uint256 toValidators = (msg.value * VALIDATORS_PERCENTAGE) / 100;
        uint256 toBurn = (msg.value * BURN_PERCENTAGE) / 100;
        uint256 toTreasury = msg.value - toStakers - toValidators - toBurn;

        pendingStakerPool += toStakers;
        pendingValidatorPool += toValidators;

        // Burn portion
        if (toBurn > 0) {
            burnContract.burnBridgeFees{value: toBurn}();
            stats.burned += toBurn;
        }

        // Send to treasury
        if (toTreasury > 0) {
            (bool success, ) = treasuryAddress.call{value: toTreasury}("");
            require(success, "Treasury transfer failed");
            stats.toTreasury += toTreasury;
        }

        emit RevenueReceived(msg.sender, msg.value, source);

        // Auto-distribute if threshold reached
        if (pendingStakerPool >= MIN_DISTRIBUTION_AMOUNT) {
            _distributeToStakers();
        }
        if (pendingValidatorPool >= MIN_DISTRIBUTION_AMOUNT) {
            _distributeToValidators();
        }
    }

    /**
     * @notice Distribute pending rewards to stakers
     */
    function distributeToStakers() external nonReentrant {
        require(pendingStakerPool > 0, "No pending rewards");
        _distributeToStakers();
    }

    /**
     * @notice Internal distribution to stakers
     */
    function _distributeToStakers() internal {
        uint256 totalStaked = stakingContract.totalStaked();
        require(totalStaked > 0, "No stakers");

        uint256 amount = pendingStakerPool;
        pendingStakerPool = 0;

        // Note: In production, we'd iterate through stakers or use a snapshot
        // For now, we'll keep rewards claimable per user

        stats.distributedToStakers += amount;
        emit RevenueDistributed(amount, 0, 0, 0);
    }

    /**
     * @notice Distribute pending rewards to validators
     */
    function distributeToValidators() external nonReentrant {
        require(pendingValidatorPool > 0, "No pending rewards");
        _distributeToValidators();
    }

    /**
     * @notice Internal distribution to validators
     */
    function _distributeToValidators() internal {
        uint256 validatorCount = getValidatorCount();
        require(validatorCount > 0, "No validators");

        uint256 amount = pendingValidatorPool;
        pendingValidatorPool = 0;

        uint256 perValidator = amount / validatorCount;

        // In production, iterate through validator list
        // For now, track as claimable rewards

        stats.distributedToValidators += amount;
        emit RevenueDistributed(0, amount, 0, 0);
    }

    /**
     * @notice Claim staker rewards
     */
    function claimStakerRewards() external nonReentrant {
        uint256 reward = calculateStakerReward(msg.sender);
        require(reward > 0, "No rewards available");

        stakerRewards[msg.sender] = 0;

        (bool success, ) = msg.sender.call{value: reward}("");
        require(success, "Transfer failed");

        emit StakerRewardClaimed(msg.sender, reward);
    }

    /**
     * @notice Claim validator rewards
     */
    function claimValidatorRewards() external nonReentrant {
        require(isValidator[msg.sender], "Not a validator");
        uint256 reward = validatorRewards[msg.sender];
        require(reward > 0, "No rewards available");

        validatorRewards[msg.sender] = 0;

        (bool success, ) = msg.sender.call{value: reward}("");
        require(success, "Transfer failed");

        emit ValidatorRewardClaimed(msg.sender, reward);
    }

    /**
     * @notice Calculate staker's share of revenue
     * @param staker Address to check
     * @return Pending reward amount
     */
    function calculateStakerReward(address staker) public view returns (uint256) {
        uint256 totalStaked = stakingContract.totalStaked();
        if (totalStaked == 0) return 0;

        (uint256 stakedAmount, , , , , ) = stakingContract.stakes(staker);
        if (stakedAmount == 0) return 0;

        uint256 share = (stats.distributedToStakers * stakedAmount) / totalStaked;
        return share + stakerRewards[staker];
    }

    /**
     * @notice Get validator count
     */
    function getValidatorCount() public view returns (uint256) {
        // In production, maintain a validator array
        // For now, return a fixed count
        return 3; // Three validators
    }

    // ============ Admin Functions ============

    /**
     * @notice Add a validator
     */
    function addValidator(address validator) external onlyOwner {
        require(!isValidator[validator], "Already validator");
        isValidator[validator] = true;
        emit ValidatorAdded(validator);
    }

    /**
     * @notice Remove a validator
     */
    function removeValidator(address validator) external onlyOwner {
        require(isValidator[validator], "Not a validator");
        isValidator[validator] = false;
        emit ValidatorRemoved(validator);
    }

    /**
     * @notice Update treasury address
     */
    function updateTreasuryAddress(address _treasuryAddress) external onlyOwner {
        treasuryAddress = _treasuryAddress;
    }

    /**
     * @notice Update staking contract
     */
    function updateStakingContract(address _stakingContract) external onlyOwner {
        stakingContract = IXHTStaking(_stakingContract);
    }

    /**
     * @notice Update burn contract
     */
    function updateBurnContract(address _burnContract) external onlyOwner {
        burnContract = IXHTBurnMechanism(_burnContract);
    }

    // ============ View Functions ============

    /**
     * @notice Get complete revenue statistics
     */
    function getRevenueStats() external view returns (
        uint256 totalCollected,
        uint256 distributedToStakers,
        uint256 distributedToValidators,
        uint256 burned,
        uint256 toTreasury,
        uint256 pendingStakers,
        uint256 pendingValidators
    ) {
        return (
            stats.totalCollected,
            stats.distributedToStakers,
            stats.distributedToValidators,
            stats.burned,
            stats.toTreasury,
            pendingStakerPool,
            pendingValidatorPool
        );
    }

    /**
     * @notice Get distribution breakdown for an amount
     */
    function getDistributionBreakdown(uint256 amount) external pure returns (
        uint256 toStakers,
        uint256 toValidators,
        uint256 toBurn,
        uint256 toTreasury
    ) {
        toStakers = (amount * STAKERS_PERCENTAGE) / 100;
        toValidators = (amount * VALIDATORS_PERCENTAGE) / 100;
        toBurn = (amount * BURN_PERCENTAGE) / 100;
        toTreasury = amount - toStakers - toValidators - toBurn;

        return (toStakers, toValidators, toBurn, toTreasury);
    }

    // ============ Receive Function ============

    receive() external payable {
        stats.totalCollected += msg.value;
        emit RevenueReceived(msg.sender, msg.value, "direct");
    }
}

contracts/tokenomics/XHTStaking.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/security/ReentrancyGuard.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/security/Pausable.sol";

/**
 * @title XHTStaking
 * @notice Intelligent staking contract for XHT (Xaheen Token)
 * @dev Features:
 * - Dynamic APY (8-20%) based on network security needs
 * - Lock period multipliers (up to 3x voting power)
 * - Revenue sharing (50% of protocol revenue)
 * - Automatic compounding
 */
contract XHTStaking is ReentrancyGuard, Ownable, Pausable {

    // ============ State Variables ============

    struct StakeInfo {
        uint256 amount;           // Amount staked
        uint256 startTime;        // When stake started
        uint256 lockPeriod;       // Lock duration (0, 90, 180, 365 days)
        uint256 lastRewardTime;   // Last reward claim
        uint256 accumulatedRewards; // Pending rewards
        bool isValidator;         // Validator status (5x voting power)
    }

    struct LockTier {
        uint256 duration;         // Lock period in days
        uint256 votingMultiplier; // Voting power multiplier (100 = 1x)
        uint256 rewardBonus;      // Reward bonus percentage
    }

    mapping(address => StakeInfo) public stakes;
    mapping(uint256 => LockTier) public lockTiers;

    uint256 public totalStaked;
    uint256 public totalSupply = 1_000_000_000 ether; // 1 billion XHT
    uint256 public targetStakePercentage = 30; // 30% of supply
    uint256 public revenuePool; // Protocol revenue for distribution

    uint256 public constant MIN_STAKE = 1000 ether; // 1,000 XHT minimum
    uint256 public constant VALIDATOR_STAKE = 10_000 ether; // 10,000 XHT for validator
    uint256 public constant BASE_APY_MIN = 8; // 8% minimum APY
    uint256 public constant BASE_APY_MAX = 20; // 20% maximum APY

    // ============ Events ============

    event Staked(address indexed user, uint256 amount, uint256 lockPeriod);
    event Unstaked(address indexed user, uint256 amount, uint256 reward);
    event RewardsClaimed(address indexed user, uint256 reward);
    event RevenueAdded(uint256 amount);
    event ValidatorStatusUpdated(address indexed user, bool isValidator);

    // ============ Constructor ============

    constructor() {
        // Initialize lock tiers
        lockTiers[0] = LockTier(0, 100, 0);      // No lock: 1x voting, 0% bonus
        lockTiers[1] = LockTier(90, 150, 5);     // 3 months: 1.5x voting, 5% bonus
        lockTiers[2] = LockTier(180, 200, 15);   // 6 months: 2x voting, 15% bonus
        lockTiers[3] = LockTier(365, 300, 30);   // 12 months: 3x voting, 30% bonus
        lockTiers[4] = LockTier(1095, 500, 200); // 36 months: 5x voting, 200% bonus
    }

    // ============ Core Functions ============

    /**
     * @notice Stake XHT tokens
     * @param amount Amount to stake (must be >= MIN_STAKE)
     * @param lockTierId Lock tier (0-4)
     */
    function stake(uint256 amount, uint256 lockTierId) external payable nonReentrant whenNotPaused {
        require(msg.value == amount, "Amount mismatch");
        require(amount >= MIN_STAKE, "Below minimum stake");
        require(lockTierId <= 4, "Invalid lock tier");
        require(stakes[msg.sender].amount == 0, "Already staking");

        LockTier memory tier = lockTiers[lockTierId];

        stakes[msg.sender] = StakeInfo({
            amount: amount,
            startTime: block.timestamp,
            lockPeriod: tier.duration * 1 days,
            lastRewardTime: block.timestamp,
            accumulatedRewards: 0,
            isValidator: amount >= VALIDATOR_STAKE
        });

        totalStaked += amount;

        emit Staked(msg.sender, amount, tier.duration);

        if (amount >= VALIDATOR_STAKE) {
            emit ValidatorStatusUpdated(msg.sender, true);
        }
    }

    /**
     * @notice Unstake XHT tokens and claim rewards
     */
    function unstake() external nonReentrant {
        StakeInfo storage stakeInfo = stakes[msg.sender];
        require(stakeInfo.amount > 0, "No stake found");
        require(block.timestamp >= stakeInfo.startTime + stakeInfo.lockPeriod, "Still locked");

        uint256 reward = calculateReward(msg.sender);
        uint256 totalAmount = stakeInfo.amount + reward;

        totalStaked -= stakeInfo.amount;

        emit Unstaked(msg.sender, stakeInfo.amount, reward);

        delete stakes[msg.sender];

        (bool success, ) = msg.sender.call{value: totalAmount}("");
        require(success, "Transfer failed");
    }

    /**
     * @notice Claim accumulated rewards without unstaking
     */
    function claimRewards() external nonReentrant {
        StakeInfo storage stakeInfo = stakes[msg.sender];
        require(stakeInfo.amount > 0, "No stake found");

        uint256 reward = calculateReward(msg.sender);
        require(reward > 0, "No rewards available");

        stakeInfo.lastRewardTime = block.timestamp;
        stakeInfo.accumulatedRewards = 0;

        emit RewardsClaimed(msg.sender, reward);

        (bool success, ) = msg.sender.call{value: reward}("");
        require(success, "Transfer failed");
    }

    /**
     * @notice Calculate dynamic APY based on total staked
     * @return APY percentage (8-20%)
     */
    function calculateDynamicAPY() public view returns (uint256) {
        uint256 targetStake = (totalSupply * targetStakePercentage) / 100;

        if (totalStaked < targetStake) {
            // Incentivize more staking
            uint256 stakingRatio = (totalStaked * 100) / targetStake;
            return BASE_APY_MAX - ((BASE_APY_MAX - BASE_APY_MIN) * stakingRatio) / 100;
        } else {
            // Gradually reduce as security improves
            return BASE_APY_MIN;
        }
    }

    /**
     * @notice Calculate pending rewards for a user
     * @param user Address to check
     * @return Pending reward amount
     */
    function calculateReward(address user) public view returns (uint256) {
        StakeInfo memory stakeInfo = stakes[user];
        if (stakeInfo.amount == 0) return 0;

        uint256 stakingTime = block.timestamp - stakeInfo.lastRewardTime;
        uint256 baseAPY = calculateDynamicAPY();

        // Get lock tier bonus
        uint256 lockTierId = getLockTierId(stakeInfo.lockPeriod);
        uint256 rewardBonus = lockTiers[lockTierId].rewardBonus;

        // Calculate base reward
        uint256 baseReward = (stakeInfo.amount * baseAPY * stakingTime) / (365 days * 100);

        // Apply lock bonus
        uint256 bonusReward = (baseReward * rewardBonus) / 100;

        // Add revenue share
        uint256 revenueShare = calculateRevenueShare(user);

        return baseReward + bonusReward + revenueShare + stakeInfo.accumulatedRewards;
    }

    /**
     * @notice Calculate revenue share for a user (50% of protocol revenue)
     * @param user Address to check
     * @return Revenue share amount
     */
    function calculateRevenueShare(address user) public view returns (uint256) {
        if (totalStaked == 0) return 0;

        StakeInfo memory stakeInfo = stakes[user];
        uint256 userShare = (stakeInfo.amount * 1e18) / totalStaked;
        uint256 distributionPool = (revenuePool * 50) / 100; // 50% to stakers

        return (distributionPool * userShare) / 1e18;
    }

    /**
     * @notice Get voting power for governance
     * @param user Address to check
     * @return Voting power (with multipliers)
     */
    function getVotingPower(address user) external view returns (uint256) {
        StakeInfo memory stakeInfo = stakes[user];
        if (stakeInfo.amount == 0) return 0;

        uint256 lockTierId = getLockTierId(stakeInfo.lockPeriod);
        uint256 multiplier = lockTiers[lockTierId].votingMultiplier;

        // Apply validator multiplier (5x)
        if (stakeInfo.isValidator) {
            multiplier *= 5;
        }

        return (stakeInfo.amount * multiplier) / 100;
    }

    /**
     * @notice Get lock tier ID from lock period
     */
    function getLockTierId(uint256 lockPeriod) internal pure returns (uint256) {
        if (lockPeriod == 0) return 0;
        if (lockPeriod == 90 days) return 1;
        if (lockPeriod == 180 days) return 2;
        if (lockPeriod == 365 days) return 3;
        if (lockPeriod == 1095 days) return 4;
        return 0;
    }

    // ============ Admin Functions ============

    /**
     * @notice Add protocol revenue for distribution
     */
    function addRevenue() external payable onlyOwner {
        revenuePool += msg.value;
        emit RevenueAdded(msg.value);
    }

    /**
     * @notice Update target stake percentage
     */
    function setTargetStakePercentage(uint256 percentage) external onlyOwner {
        require(percentage > 0 && percentage <= 100, "Invalid percentage");
        targetStakePercentage = percentage;
    }

    /**
     * @notice Emergency pause
     */
    function pause() external onlyOwner {
        _pause();
    }

    /**
     * @notice Unpause
     */
    function unpause() external onlyOwner {
        _unpause();
    }

    // ============ View Functions ============

    /**
     * @notice Get complete stake information
     */
    function getStakeInfo(address user) external view returns (
        uint256 amount,
        uint256 startTime,
        uint256 lockPeriod,
        uint256 pendingRewards,
        uint256 votingPower,
        uint256 currentAPY,
        bool isValidator
    ) {
        StakeInfo memory stakeInfo = stakes[user];
        return (
            stakeInfo.amount,
            stakeInfo.startTime,
            stakeInfo.lockPeriod,
            calculateReward(user),
            this.getVotingPower(user),
            calculateDynamicAPY(),
            stakeInfo.isValidator
        );
    }

    /**
     * @notice Get total staking statistics
     */
    function getStats() external view returns (
        uint256 _totalStaked,
        uint256 _totalSupply,
        uint256 stakingPercentage,
        uint256 currentAPY,
        uint256 _revenuePool
    ) {
        return (
            totalStaked,
            totalSupply,
            (totalStaked * 100) / totalSupply,
            calculateDynamicAPY(),
            revenuePool
        );
    }
}

